window.COURSE={"lessons":[{"id":1,"level":"入門","title":"第一聲：あいうえお","pattern":"一個假名，一個拍子","note":"日文的あ、い、う、え、お各佔一拍。う的嘴唇放鬆，不必像中文「烏」一樣用力噘嘴。先聽再模仿，不用急著記漢字。","words":[{"jp":"あ","kana":"あ","zh":"a；嘴巴自然張開"},{"jp":"い","kana":"い","zh":"i；嘴角稍微向兩側"},{"jp":"う","kana":"う","zh":"u；嘴唇放鬆"},{"jp":"え","kana":"え","zh":"e；介於欸與耶的母音"},{"jp":"お","kana":"お","zh":"o；嘴型圓一些"},{"jp":"あお","kana":"あお","zh":"藍色"},{"jp":"いえ","kana":"いえ","zh":"家"},{"jp":"うえ","kana":"うえ","zh":"上面"}],"examples":[{"jp":"あ、い、う、え、お。","kana":"あ、い、う、え、お。","zh":"依序練習五個母音。"},{"jp":"あお。","kana":"あお。","zh":"藍色。"},{"jp":"いえ。","kana":"いえ。","zh":"家。"}],"quiz":{"prompt":"「いえ」有幾拍？","answer":"兩拍","wrong":["一拍","四拍"],"why":"い和え各一拍。先把節奏聽清楚，再看字形。"}},{"id":2,"level":"入門","title":"把聲音連起來","pattern":"か・さ・た・な 行","note":"每個音節等長。し讀 shi，ち讀 chi，つ讀 tsu，ふ讀 fu，不能直接照羅馬字逐字讀。這一課先練か、さ、た、な四行。","words":[{"jp":"かさ","kana":"かさ","zh":"雨傘"},{"jp":"すし","kana":"すし","zh":"壽司"},{"jp":"たこ","kana":"たこ","zh":"章魚"},{"jp":"ねこ","kana":"ねこ","zh":"貓"},{"jp":"いぬ","kana":"いぬ","zh":"狗"},{"jp":"なつ","kana":"なつ","zh":"夏天"},{"jp":"した","kana":"した","zh":"下面"},{"jp":"つき","kana":"つき","zh":"月亮"}],"examples":[{"jp":"かさ。","kana":"かさ。","zh":"雨傘。"},{"jp":"すし。","kana":"すし。","zh":"壽司。"},{"jp":"ねこ。","kana":"ねこ。","zh":"貓。"}],"quiz":{"prompt":"「貓」是哪一個？","answer":"ねこ","wrong":["いぬ","かさ"],"why":"ねこ是貓，いぬ是狗。"}},{"id":3,"level":"入門","title":"走完平假名","pattern":"は・ま・や・ら・わ・ん","note":"や行只有や、ゆ、よ。ら行是舌尖輕碰一下。を作助詞時讀お；は作主題助詞時讀わ；へ作方向助詞時讀え。ん也要佔一拍。","words":[{"jp":"はな","kana":"はな","zh":"花"},{"jp":"みみ","kana":"みみ","zh":"耳朵"},{"jp":"やま","kana":"やま","zh":"山"},{"jp":"ゆき","kana":"ゆき","zh":"雪"},{"jp":"よる","kana":"よる","zh":"夜晚"},{"jp":"そら","kana":"そら","zh":"天空"},{"jp":"わたし","kana":"わたし","zh":"我"},{"jp":"ほん","kana":"ほん","zh":"書"}],"examples":[{"jp":"はな。","kana":"はな。","zh":"花。"},{"jp":"やま。","kana":"やま。","zh":"山。"},{"jp":"ほん。","kana":"ほん。","zh":"書。"}],"quiz":{"prompt":"主題助詞「は」怎麼讀？","answer":"わ","wrong":["は","へ"],"why":"主題助詞は讀わ，例如わたしは。字詞中的は通常仍讀ha。"}},{"id":4,"level":"入門","title":"濁音與半濁音","pattern":"が・ざ・だ・ば・ぱ","note":"右上兩點變濁音，小圓圈把は行變成ぱ行。じ和ぢ、ず和づ在標準日語通常同音，但寫法依單字而定。","words":[{"jp":"かぎ","kana":"かぎ","zh":"鑰匙"},{"jp":"みず","kana":"みず","zh":"水"},{"jp":"でんわ","kana":"でんわ","zh":"電話"},{"jp":"かばん","kana":"かばん","zh":"包包"},{"jp":"パン","kana":"ぱん","zh":"麵包"},{"jp":"ちず","kana":"ちず","zh":"地圖"},{"jp":"ごはん","kana":"ごはん","zh":"飯"},{"jp":"だいがく","kana":"だいがく","zh":"大學"}],"examples":[{"jp":"みず。","kana":"みず。","zh":"水。"},{"jp":"かばん。","kana":"かばん。","zh":"包包。"},{"jp":"パン。","kana":"ぱん。","zh":"麵包。"}],"quiz":{"prompt":"「は」加小圓圈變成什麼？","answer":"ぱ","wrong":["ば","が"],"why":"は行加小圓圈是ぱ行；加兩點是ば行。"}},{"id":5,"level":"入門","title":"聽見長短與停頓","pattern":"長音・促音っ・撥音ん","note":"おばさん和おばあさん意思不同，長音要多一拍。小っ不讀出聲，而是停一拍；ん也佔一拍。おう多讀長o，えい常讀長e。","words":[{"jp":"おばさん","kana":"おばさん","zh":"阿姨"},{"jp":"おばあさん","kana":"おばあさん","zh":"奶奶"},{"jp":"きて","kana":"きて","zh":"請來（て形）"},{"jp":"きって","kana":"きって","zh":"郵票"},{"jp":"びょういん","kana":"びょういん","zh":"醫院"},{"jp":"びよういん","kana":"びよういん","zh":"美容院"},{"jp":"きょう","kana":"きょう","zh":"今天"},{"jp":"がっこう","kana":"がっこう","zh":"學校"}],"examples":[{"jp":"きて。きって。","kana":"きて。きって。","zh":"請來。郵票。"},{"jp":"おばさん。おばあさん。","kana":"おばさん。おばあさん。","zh":"阿姨。奶奶。"},{"jp":"がっこう。","kana":"がっこう。","zh":"學校，四拍。"}],"quiz":{"prompt":"「きって」有幾拍？","answer":"三拍","wrong":["兩拍","一拍"],"why":"き・っ・て共三拍。小っ是一拍的停頓。"}},{"id":6,"level":"入門","title":"小字也有大差別","pattern":"きゃ・しゅ・ちょ","note":"拗音用小ゃ、ゅ、ょ，和前面的音合成一拍。きゃ是一拍，きや是兩拍。京都きょうと是きょ・う・と三拍。","words":[{"jp":"きゃく","kana":"きゃく","zh":"客人"},{"jp":"しゃしん","kana":"しゃしん","zh":"照片"},{"jp":"でんしゃ","kana":"でんしゃ","zh":"電車"},{"jp":"りょかん","kana":"りょかん","zh":"日式旅館"},{"jp":"きょうと","kana":"きょうと","zh":"京都"},{"jp":"おちゃ","kana":"おちゃ","zh":"茶"},{"jp":"じゅう","kana":"じゅう","zh":"十"},{"jp":"りょうり","kana":"りょうり","zh":"料理"}],"examples":[{"jp":"きょうと。","kana":"きょうと。","zh":"京都。"},{"jp":"しゃしん。","kana":"しゃしん。","zh":"照片。"},{"jp":"りょかん。","kana":"りょかん。","zh":"日式旅館。"}],"quiz":{"prompt":"「きょうと」有幾拍？","answer":"三拍","wrong":["兩拍","四拍"],"why":"きょ一拍、う一拍、と一拍。"}},{"id":7,"level":"入門","title":"讀懂片假名招牌","pattern":"カタカナ","note":"片假名常用在外來語與商品名。長音用ー表示。シ和ツ、ソ和ン要特別比較筆畫方向。停車後可用假名表逐行練。","words":[{"jp":"ホテル","kana":"ほてる","zh":"飯店"},{"jp":"バス","kana":"ばす","zh":"公車"},{"jp":"タクシー","kana":"たくしー","zh":"計程車"},{"jp":"コーヒー","kana":"こーひー","zh":"咖啡"},{"jp":"コンビニ","kana":"こんびに","zh":"便利商店"},{"jp":"トイレ","kana":"といれ","zh":"洗手間"},{"jp":"カード","kana":"かーど","zh":"卡片"},{"jp":"メニュー","kana":"めにゅー","zh":"菜單"}],"examples":[{"jp":"ホテル。","kana":"ほてる。","zh":"飯店。"},{"jp":"コーヒー。","kana":"こーひー。","zh":"咖啡。"},{"jp":"タクシー。","kana":"たくしー。","zh":"計程車。"}],"quiz":{"prompt":"「コーヒー」的長音符號是？","answer":"ー","wrong":["っ","ゃ"],"why":"片假名通常用ー表示前一個母音延長一拍。"}},{"id":8,"level":"入門","title":"讓對話繼續下去","pattern":"すみません・もう一度","note":"不懂時先說すみません，再請對方慢慢說。ありがとうございます比どうも更完整。這些固定表達先整句記住。","words":[{"jp":"こんにちは","kana":"こんにちは","zh":"你好（白天）"},{"jp":"おはようございます","kana":"おはようございます","zh":"早安（禮貌）"},{"jp":"こんばんは","kana":"こんばんは","zh":"晚上好"},{"jp":"ありがとうございます","kana":"ありがとうございます","zh":"謝謝"},{"jp":"すみません","kana":"すみません","zh":"不好意思／抱歉"},{"jp":"はい","kana":"はい","zh":"是／好的"},{"jp":"いいえ","kana":"いいえ","zh":"不是／不"},{"jp":"ゆっくり","kana":"ゆっくり","zh":"慢慢地"}],"examples":[{"jp":"すみません。","kana":"すみません。","zh":"不好意思。"},{"jp":"もう一度お願いします。","kana":"もういちどおねがいします。","zh":"請再說一次。"},{"jp":"ゆっくり話してください。","kana":"ゆっくりはなしてください。","zh":"請慢慢說。"}],"quiz":{"prompt":"想請對方再說一次，選哪一句？","answer":"もう一度お願いします。","wrong":["いただきます。","おやすみなさい。"],"why":"もう一度是再一次。お願いします讓請求更有禮貌。"}},{"id":9,"level":"N5","title":"在京都介紹自己","pattern":"A は B です","note":"は標記主題，です讓句子禮貌。否定用じゃありません或較正式的ではありません。日文常省略已知的主語。","words":[{"jp":"私","kana":"わたし","zh":"我"},{"jp":"台湾","kana":"たいわん","zh":"台灣"},{"jp":"日本","kana":"にほん","zh":"日本"},{"jp":"学生","kana":"がくせい","zh":"學生"},{"jp":"会社員","kana":"かいしゃいん","zh":"公司職員"},{"jp":"旅行","kana":"りょこう","zh":"旅行"},{"jp":"友達","kana":"ともだち","zh":"朋友"},{"jp":"名前","kana":"なまえ","zh":"名字"}],"examples":[{"jp":"私は台湾人です。","kana":"わたしはたいわんじんです。","zh":"我是台灣人。"},{"jp":"学生じゃありません。","kana":"がくせいじゃありません。","zh":"我不是學生。"},{"jp":"旅行です。","kana":"りょこうです。","zh":"我是來旅行的。"}],"quiz":{"prompt":"私は台湾人＿＿。","answer":"です","wrong":["ます","を"],"why":"名詞句以です結尾；ます接在動詞的ます形後。"}},{"id":10,"level":"N5","title":"這個、那個、哪個","pattern":"これ／それ／あれ・この N","note":"これ可單獨使用；この後面一定接名詞。こ靠近自己，そ靠近對方，あ離雙方都遠，ど用來提問。","words":[{"jp":"これ","kana":"これ","zh":"這個"},{"jp":"それ","kana":"それ","zh":"那個（對方附近）"},{"jp":"あれ","kana":"あれ","zh":"那個（遠處）"},{"jp":"どれ","kana":"どれ","zh":"哪個"},{"jp":"この","kana":"この","zh":"這個＋名詞"},{"jp":"その","kana":"その","zh":"那個＋名詞"},{"jp":"あの","kana":"あの","zh":"那個（遠）＋名詞"},{"jp":"お土産","kana":"おみやげ","zh":"伴手禮"}],"examples":[{"jp":"これは何ですか。","kana":"これはなんですか。","zh":"這是什麼？"},{"jp":"そのお茶をください。","kana":"そのおちゃをください。","zh":"請給我那個茶。"},{"jp":"どれですか。","kana":"どれですか。","zh":"是哪一個？"}],"quiz":{"prompt":"「這本書」怎麼說？","answer":"この本","wrong":["これ本","どれ本"],"why":"この後接名詞；これ本不成立。"}},{"id":11,"level":"N5","title":"問一個好問題","pattern":"だれ・何・どこ・か","note":"禮貌問句通常句尾加か。何在不同搭配讀なに或なん；何ですか讀なんですか。だれ問人，どこ問地點。","words":[{"jp":"誰","kana":"だれ","zh":"誰"},{"jp":"何","kana":"なに","zh":"什麼"},{"jp":"どこ","kana":"どこ","zh":"哪裡"},{"jp":"いつ","kana":"いつ","zh":"什麼時候"},{"jp":"どう","kana":"どう","zh":"如何"},{"jp":"駅","kana":"えき","zh":"車站"},{"jp":"入口","kana":"いりぐち","zh":"入口"},{"jp":"出口","kana":"でぐち","zh":"出口"}],"examples":[{"jp":"駅はどこですか。","kana":"えきはどこですか。","zh":"車站在哪裡？"},{"jp":"これは何ですか。","kana":"これはなんですか。","zh":"這是什麼？"},{"jp":"お名前は何ですか。","kana":"おなまえはなんですか。","zh":"請問您的名字？"}],"quiz":{"prompt":"詢問車站位置應該用？","answer":"どこ","wrong":["だれ","いつ"],"why":"どこ問地方，だれ問人，いつ問時間。"}},{"id":12,"level":"N5","title":"我的、你的、我也是","pattern":"N の N・も","note":"の連接名詞，可表示所屬或類別。も取代は等助詞表達「也」，不能直接在は後面加も。","words":[{"jp":"本","kana":"ほん","zh":"書"},{"jp":"地図","kana":"ちず","zh":"地圖"},{"jp":"先生","kana":"せんせい","zh":"老師"},{"jp":"家族","kana":"かぞく","zh":"家人"},{"jp":"母","kana":"はは","zh":"自己的媽媽"},{"jp":"父","kana":"ちち","zh":"自己的爸爸"},{"jp":"兄","kana":"あに","zh":"自己的哥哥"},{"jp":"姉","kana":"あね","zh":"自己的姊姊"}],"examples":[{"jp":"これは私の地図です。","kana":"これはわたしのちずです。","zh":"這是我的地圖。"},{"jp":"友達も台湾人です。","kana":"ともだちもたいわんじんです。","zh":"朋友也是台灣人。"},{"jp":"日本語の本です。","kana":"にほんごのほんです。","zh":"是日文書。"}],"quiz":{"prompt":"「朋友也是學生」：友達＿＿学生です。","answer":"も","wrong":["の","を"],"why":"も表示也，直接接在友達後。"}},{"id":13,"level":"N5","title":"這裡有什麼","pattern":"場所 に N が あります／います","note":"無生命物用あります，人與動物用います。存在的地點用に，存在的對象用が。","words":[{"jp":"公園","kana":"こうえん","zh":"公園"},{"jp":"店","kana":"みせ","zh":"店"},{"jp":"銀行","kana":"ぎんこう","zh":"銀行"},{"jp":"郵便局","kana":"ゆうびんきょく","zh":"郵局"},{"jp":"猫","kana":"ねこ","zh":"貓"},{"jp":"犬","kana":"いぬ","zh":"狗"},{"jp":"子供","kana":"こども","zh":"小孩"},{"jp":"近く","kana":"ちかく","zh":"附近"}],"examples":[{"jp":"近くにコンビニがあります。","kana":"ちかくにこんびにがあります。","zh":"附近有便利商店。"},{"jp":"公園に猫がいます。","kana":"こうえんにねこがいます。","zh":"公園有貓。"},{"jp":"トイレは二階にあります。","kana":"といれはにかいにあります。","zh":"洗手間在二樓。"}],"quiz":{"prompt":"公園に猫が＿＿。","answer":"います","wrong":["あります","ですます"],"why":"貓是有生命的動物，存在用います。"}},{"id":14,"level":"N5","title":"找路的方向感","pattern":"N の 前／後ろ／隣","note":"位置詞通常透過の接在地點後，例如駅の前。詢問位置時可說どこにありますか。","words":[{"jp":"前","kana":"まえ","zh":"前面"},{"jp":"後ろ","kana":"うしろ","zh":"後面"},{"jp":"右","kana":"みぎ","zh":"右邊"},{"jp":"左","kana":"ひだり","zh":"左邊"},{"jp":"上","kana":"うえ","zh":"上面"},{"jp":"下","kana":"した","zh":"下面"},{"jp":"隣","kana":"となり","zh":"隔壁"},{"jp":"向かい","kana":"むかい","zh":"對面"}],"examples":[{"jp":"駅の前にいます。","kana":"えきのまえにいます。","zh":"我在車站前。"},{"jp":"銀行の隣です。","kana":"ぎんこうのとなりです。","zh":"在銀行隔壁。"},{"jp":"右に曲がってください。","kana":"みぎにまがってください。","zh":"請向右轉。"}],"quiz":{"prompt":"「車站前面」是？","answer":"駅の前","wrong":["駅を前","駅で前"],"why":"位置詞以前面的名詞＋の連接。"}},{"id":15,"level":"N5","title":"數量與價錢","pattern":"ひとつ・一人・一枚","note":"一到十可用ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお。人數一、二人讀ひとり、ふたり。","words":[{"jp":"一つ","kana":"ひとつ","zh":"一個"},{"jp":"二つ","kana":"ふたつ","zh":"兩個"},{"jp":"三つ","kana":"みっつ","zh":"三個"},{"jp":"一人","kana":"ひとり","zh":"一個人"},{"jp":"二人","kana":"ふたり","zh":"兩個人"},{"jp":"一枚","kana":"いちまい","zh":"一張"},{"jp":"百円","kana":"ひゃくえん","zh":"一百日圓"},{"jp":"千円","kana":"せんえん","zh":"一千日圓"}],"examples":[{"jp":"これを二つください。","kana":"これをふたつください。","zh":"這個請給我兩個。"},{"jp":"二人です。","kana":"ふたりです。","zh":"兩位。"},{"jp":"全部でいくらですか。","kana":"ぜんぶでいくらですか。","zh":"總共多少錢？"}],"quiz":{"prompt":"兩位客人進餐廳時說？","answer":"二人です。","wrong":["二つです。","二枚です。"],"why":"人數的兩位是ふたり；ふたつ算物品，枚算扁平物。"}},{"id":16,"level":"N5","title":"時間與日期","pattern":"時・分・曜日・から／まで","note":"四時讀よじ、七時讀しちじ、九時讀くじ。明確時間通常接に；今日、明日等相對時間通常不加に。から表示起點，まで表示終點。","words":[{"jp":"今日","kana":"きょう","zh":"今天"},{"jp":"明日","kana":"あした","zh":"明天"},{"jp":"昨日","kana":"きのう","zh":"昨天"},{"jp":"朝","kana":"あさ","zh":"早上"},{"jp":"昼","kana":"ひる","zh":"中午"},{"jp":"夜","kana":"よる","zh":"晚上"},{"jp":"月曜日","kana":"げつようび","zh":"星期一"},{"jp":"半","kana":"はん","zh":"半"}],"examples":[{"jp":"九時に出ます。","kana":"くじにでます。","zh":"九點出發。"},{"jp":"十時から五時までです。","kana":"じゅうじからごじまでです。","zh":"從十點到五點。"},{"jp":"明日、京都に行きます。","kana":"あした、きょうとにいきます。","zh":"明天去京都。"}],"quiz":{"prompt":"「四點」的正確讀音？","answer":"よじ","wrong":["よんじ","しじ"],"why":"時間四時固定讀よじ。"}},{"id":17,"level":"N5","title":"每天做的事","pattern":"動詞ます・ません","note":"ます是禮貌的非過去形，可表習慣或未來。ません是否定。動詞三類：五段、一段、不規則する與来る，後續變化要分開學。","words":[{"jp":"行く","kana":"いく","zh":"去"},{"jp":"来る","kana":"くる","zh":"來"},{"jp":"帰る","kana":"かえる","zh":"回去"},{"jp":"食べる","kana":"たべる","zh":"吃"},{"jp":"飲む","kana":"のむ","zh":"喝"},{"jp":"見る","kana":"みる","zh":"看"},{"jp":"聞く","kana":"きく","zh":"聽／問"},{"jp":"する","kana":"する","zh":"做"}],"examples":[{"jp":"毎日、お茶を飲みます。","kana":"まいにち、おちゃをのみます。","zh":"每天喝茶。"},{"jp":"朝ご飯を食べません。","kana":"あさごはんをたべません。","zh":"不吃早餐。"},{"jp":"明日、京都に行きます。","kana":"あした、きょうとにいきます。","zh":"明天去京都。"}],"quiz":{"prompt":"飲みます的禮貌否定形？","answer":"飲みません","wrong":["飲みました","飲みたい"],"why":"ません表示非過去否定，ました是過去肯定。"}},{"id":18,"level":"N5","title":"昨天做了什麼","pattern":"ました・ませんでした","note":"禮貌過去肯定是ました，過去否定是ませんでした。日文動詞不因為主語是我或你而改變。","words":[{"jp":"買う","kana":"かう","zh":"買"},{"jp":"歩く","kana":"あるく","zh":"走路"},{"jp":"待つ","kana":"まつ","zh":"等"},{"jp":"読む","kana":"よむ","zh":"讀"},{"jp":"書く","kana":"かく","zh":"寫"},{"jp":"話す","kana":"はなす","zh":"說話"},{"jp":"会う","kana":"あう","zh":"見面"},{"jp":"休む","kana":"やすむ","zh":"休息"}],"examples":[{"jp":"昨日、お土産を買いました。","kana":"きのう、おみやげをかいました。","zh":"昨天買了伴手禮。"},{"jp":"バスに乗りませんでした。","kana":"ばすにのりませんでした。","zh":"沒有搭公車。"},{"jp":"たくさん歩きました。","kana":"たくさんあるきました。","zh":"走了很多路。"}],"quiz":{"prompt":"「昨天沒有買」怎麼說？","answer":"買いませんでした","wrong":["買いません","買いました"],"why":"過去否定用ませんでした。"}},{"id":19,"level":"N5","title":"去哪裡、怎麼去","pattern":"目的地 に／へ・交通工具 で","note":"に或へ標示移動目的地，で標示交通工具。步行固定說歩いて，不能說歩きで。","words":[{"jp":"電車","kana":"でんしゃ","zh":"電車"},{"jp":"地下鉄","kana":"ちかてつ","zh":"地下鐵"},{"jp":"自転車","kana":"じてんしゃ","zh":"腳踏車"},{"jp":"飛行機","kana":"ひこうき","zh":"飛機"},{"jp":"新幹線","kana":"しんかんせん","zh":"新幹線"},{"jp":"空港","kana":"くうこう","zh":"機場"},{"jp":"京都駅","kana":"きょうとえき","zh":"京都車站"},{"jp":"歩いて","kana":"あるいて","zh":"走路"}],"examples":[{"jp":"電車で京都へ行きます。","kana":"でんしゃできょうとへいきます。","zh":"搭電車去京都。"},{"jp":"歩いて帰ります。","kana":"あるいてかえります。","zh":"走路回去。"},{"jp":"空港に行きます。","kana":"くうこうにいきます。","zh":"去機場。"}],"quiz":{"prompt":"「搭公車去」：バス＿＿行きます。","answer":"で","wrong":["を","が"],"why":"交通工具後用で；移動目的地用に或へ。"}},{"id":20,"level":"N5","title":"在哪裡做什麼","pattern":"場所 で・受詞 を","note":"で標示動作發生的地方，を標示動作對象。存在句的地點通常用に，不要混淆。","words":[{"jp":"朝ご飯","kana":"あさごはん","zh":"早餐"},{"jp":"昼ご飯","kana":"ひるごはん","zh":"午餐"},{"jp":"晩ご飯","kana":"ばんごはん","zh":"晚餐"},{"jp":"水","kana":"みず","zh":"水"},{"jp":"写真","kana":"しゃしん","zh":"照片"},{"jp":"切符","kana":"きっぷ","zh":"車票"},{"jp":"新聞","kana":"しんぶん","zh":"報紙"},{"jp":"音楽","kana":"おんがく","zh":"音樂"}],"examples":[{"jp":"店で昼ご飯を食べます。","kana":"みせでひるごはんをたべます。","zh":"在店裡吃午餐。"},{"jp":"切符を買います。","kana":"きっぷをかいます。","zh":"買車票。"},{"jp":"公園で写真を撮ります。","kana":"こうえんでしゃしんをとります。","zh":"在公園拍照。"}],"quiz":{"prompt":"「在飯店吃」：ホテル＿＿食べます。","answer":"で","wrong":["に","を"],"why":"吃是動作，動作場所用で。"}},{"id":21,"level":"N5","title":"形容眼前的京都","pattern":"い形容詞・な形容詞","note":"い形容詞直接修飾名詞：おいしいお茶。な形容詞接な：静かな町。きれい、嫌い雖然以い結尾，卻屬於な形容詞。","words":[{"jp":"おいしい","kana":"おいしい","zh":"好吃的"},{"jp":"高い","kana":"たかい","zh":"高的／貴的"},{"jp":"安い","kana":"やすい","zh":"便宜的"},{"jp":"大きい","kana":"おおきい","zh":"大的"},{"jp":"小さい","kana":"ちいさい","zh":"小的"},{"jp":"静か","kana":"しずか","zh":"安靜"},{"jp":"きれい","kana":"きれい","zh":"漂亮／乾淨"},{"jp":"便利","kana":"べんり","zh":"方便"}],"examples":[{"jp":"おいしいお茶です。","kana":"おいしいおちゃです。","zh":"是好喝的茶。"},{"jp":"静かな町です。","kana":"しずかなまちです。","zh":"是安靜的城鎮。"},{"jp":"このホテルは便利です。","kana":"このほてるはべんりです。","zh":"這間飯店很方便。"}],"quiz":{"prompt":"「安靜的飯店」是？","answer":"静かなホテル","wrong":["静かいホテル","静かホテル"],"why":"静か是な形容詞，修飾名詞時接な。"}},{"id":22,"level":"N5","title":"描述過去與否定","pattern":"くない・かった・でした","note":"い形容詞去い加くない、かった、くなかった。いい的變化從よい出發：よくない、よかった。な形容詞與名詞用じゃない、でした。","words":[{"jp":"暑い","kana":"あつい","zh":"天氣熱"},{"jp":"寒い","kana":"さむい","zh":"天氣冷"},{"jp":"忙しい","kana":"いそがしい","zh":"忙碌"},{"jp":"楽しい","kana":"たのしい","zh":"開心"},{"jp":"新しい","kana":"あたらしい","zh":"新"},{"jp":"古い","kana":"ふるい","zh":"舊"},{"jp":"いい","kana":"いい","zh":"好"},{"jp":"有名","kana":"ゆうめい","zh":"有名"}],"examples":[{"jp":"昨日は寒かったです。","kana":"きのうはさむかったです。","zh":"昨天很冷。"},{"jp":"高くないです。","kana":"たかくないです。","zh":"不貴。"},{"jp":"静かでした。","kana":"しずかでした。","zh":"之前很安靜。"}],"quiz":{"prompt":"「很好（過去）」怎麼說？","answer":"よかったです","wrong":["いかったです","いいでした"],"why":"いい變化時用よ的詞幹，所以是よかった。"}},{"id":23,"level":"N5","title":"喜歡與擅長","pattern":"N が 好き／上手・N が ほしい","note":"好き與上手是な形容詞，對象常用が。形容自己時說得意比自稱上手自然。ほしい表示想要某物。","words":[{"jp":"好き","kana":"すき","zh":"喜歡"},{"jp":"嫌い","kana":"きらい","zh":"討厭"},{"jp":"上手","kana":"じょうず","zh":"擅長（稱讚他人）"},{"jp":"得意","kana":"とくい","zh":"拿手"},{"jp":"下手","kana":"へた","zh":"不擅長"},{"jp":"抹茶","kana":"まっちゃ","zh":"抹茶"},{"jp":"映画","kana":"えいが","zh":"電影"},{"jp":"料理","kana":"りょうり","zh":"料理"}],"examples":[{"jp":"抹茶が好きです。","kana":"まっちゃがすきです。","zh":"我喜歡抹茶。"},{"jp":"日本語が上手ですね。","kana":"にほんごがじょうずですね。","zh":"您的日文真好。"},{"jp":"地図がほしいです。","kana":"ちずがほしいです。","zh":"我想要地圖。"}],"quiz":{"prompt":"「喜歡茶」：お茶＿＿好きです。","answer":"が","wrong":["を","で"],"why":"好き的對象通常用が。"}},{"id":24,"level":"N5","title":"一起喝杯茶","pattern":"ませんか・ましょう・ましょうか","note":"ませんか是禮貌邀請；ましょう表示一起做；ましょうか可提議幫忙。注意否定問句在這裡不是拒絕。","words":[{"jp":"一緒に","kana":"いっしょに","zh":"一起"},{"jp":"少し","kana":"すこし","zh":"一點"},{"jp":"ちょっと","kana":"ちょっと","zh":"稍微／有點"},{"jp":"今","kana":"いま","zh":"現在"},{"jp":"後で","kana":"あとで","zh":"稍後"},{"jp":"喫茶店","kana":"きっさてん","zh":"咖啡茶飲店"},{"jp":"散歩","kana":"さんぽ","zh":"散步"},{"jp":"休憩","kana":"きゅうけい","zh":"休息"}],"examples":[{"jp":"一緒にお茶を飲みませんか。","kana":"いっしょにおちゃをのみませんか。","zh":"要不要一起喝茶？"},{"jp":"少し休みましょう。","kana":"すこしやすみましょう。","zh":"休息一下吧。"},{"jp":"写真を撮りましょうか。","kana":"しゃしんをとりましょうか。","zh":"需要我幫您拍照嗎？"}],"quiz":{"prompt":"想邀請對方喝茶，用？","answer":"飲みませんか","wrong":["飲みませんでした","飲まないで"],"why":"ませんか可作禮貌邀請。"}},{"id":25,"level":"N5","title":"我想去看看","pattern":"ます詞幹＋たい・目的 に 行く","note":"把ます去掉接たい表想做；たい像い形容詞變化。ます詞幹加に行く表示去做某事，例如食べに行きます。","words":[{"jp":"食べたい","kana":"たべたい","zh":"想吃"},{"jp":"行きたい","kana":"いきたい","zh":"想去"},{"jp":"買い物","kana":"かいもの","zh":"購物"},{"jp":"観光","kana":"かんこう","zh":"觀光"},{"jp":"お寺","kana":"おてら","zh":"寺院"},{"jp":"神社","kana":"じんじゃ","zh":"神社"},{"jp":"庭","kana":"にわ","zh":"庭院"},{"jp":"景色","kana":"けしき","zh":"風景"}],"examples":[{"jp":"京都に行きたいです。","kana":"きょうとにいきたいです。","zh":"我想去京都。"},{"jp":"抹茶を飲みたいです。","kana":"まっちゃをのみたいです。","zh":"我想喝抹茶。"},{"jp":"昼ご飯を食べに行きます。","kana":"ひるごはんをたべにいきます。","zh":"去吃午餐。"}],"quiz":{"prompt":"「去買」：買い＿＿行きます。","answer":"に","wrong":["を","が"],"why":"ます詞幹＋に行く表示移動的目的。"}},{"id":26,"level":"N5","title":"動詞的萬用連接器","pattern":"て形","note":"五段：うつる→って、むぶぬ→んで、く→いて、ぐ→いで、す→して；行く例外為行って。一段去る加て；する→して、来る→来て。","words":[{"jp":"食べて","kana":"たべて","zh":"吃（て形）"},{"jp":"飲んで","kana":"のんで","zh":"喝（て形）"},{"jp":"待って","kana":"まって","zh":"等（て形）"},{"jp":"書いて","kana":"かいて","zh":"寫（て形）"},{"jp":"話して","kana":"はなして","zh":"說（て形）"},{"jp":"行って","kana":"いって","zh":"去（て形）"},{"jp":"来て","kana":"きて","zh":"來（て形）"},{"jp":"して","kana":"して","zh":"做（て形）"}],"examples":[{"jp":"駅に行って、お茶を買います。","kana":"えきにいって、おちゃをかいます。","zh":"去車站買茶。"},{"jp":"ここに書いてください。","kana":"ここにかいてください。","zh":"請寫在這裡。"},{"jp":"少し待ってください。","kana":"すこしまってください。","zh":"請稍等。"}],"quiz":{"prompt":"「飲む」的て形是？","answer":"飲んで","wrong":["飲って","飲いて"],"why":"む、ぶ、ぬ結尾的五段動詞，て形是んで。"}},{"id":27,"level":"N5","title":"禮貌請求與許可","pattern":"てください・てもいいですか","note":"てください請對方做；てもいいですか詢問允許。對店員的請求也常用お願いします。","words":[{"jp":"開ける","kana":"あける","zh":"打開"},{"jp":"閉める","kana":"しめる","zh":"關上"},{"jp":"入る","kana":"はいる","zh":"進入"},{"jp":"座る","kana":"すわる","zh":"坐"},{"jp":"使う","kana":"つかう","zh":"使用"},{"jp":"撮る","kana":"とる","zh":"拍攝"},{"jp":"教える","kana":"おしえる","zh":"告訴／教"},{"jp":"見せる","kana":"みせる","zh":"出示"}],"examples":[{"jp":"もう一度言ってください。","kana":"もういちどいってください。","zh":"請再說一次。"},{"jp":"ここに座ってもいいですか。","kana":"ここにすわってもいいですか。","zh":"我可以坐這裡嗎？"},{"jp":"写真を撮ってもいいですか。","kana":"しゃしんをとってもいいですか。","zh":"可以拍照嗎？"}],"quiz":{"prompt":"想問「可以拍照嗎？」用？","answer":"撮ってもいいですか","wrong":["撮ってはいけません","撮りませんでした"],"why":"てもいいですか是詢問許可。"}},{"id":28,"level":"N5","title":"看懂禁止與提醒","pattern":"ないでください・てはいけません","note":"五段う段改あ段加ない，う結尾改わない；一段去る加ない。する→しない、来る→こない。ないでください是請不要；てはいけません是禁止。","words":[{"jp":"吸う","kana":"すう","zh":"吸（菸）"},{"jp":"触る","kana":"さわる","zh":"碰觸"},{"jp":"入れる","kana":"いれる","zh":"放入"},{"jp":"忘れる","kana":"わすれる","zh":"忘記"},{"jp":"止める","kana":"とめる","zh":"停下／停放"},{"jp":"禁煙","kana":"きんえん","zh":"禁菸"},{"jp":"禁止","kana":"きんし","zh":"禁止"},{"jp":"危ない","kana":"あぶない","zh":"危險"}],"examples":[{"jp":"ここで写真を撮らないでください。","kana":"ここでしゃしんをとらないでください。","zh":"請不要在這裡拍照。"},{"jp":"入ってはいけません。","kana":"はいってはいけません。","zh":"不可以進入。"},{"jp":"忘れないでください。","kana":"わすれないでください。","zh":"請不要忘記。"}],"quiz":{"prompt":"「買う」的ない形？","answer":"買わない","wrong":["買あない","買いない"],"why":"う結尾的五段動詞否定變成わない。"}},{"id":29,"level":"N5","title":"現在正在、一直保持","pattern":"ている・ています","note":"ている可表示進行，也可表示結果狀態。住んでいます是住在；知っています是知道，否定常說知りません。","words":[{"jp":"住む","kana":"すむ","zh":"住"},{"jp":"働く","kana":"はたらく","zh":"工作"},{"jp":"知る","kana":"しる","zh":"得知"},{"jp":"持つ","kana":"もつ","zh":"拿／持有"},{"jp":"着る","kana":"きる","zh":"穿（上身）"},{"jp":"結婚","kana":"けっこん","zh":"結婚"},{"jp":"勉強","kana":"べんきょう","zh":"學習"},{"jp":"今週","kana":"こんしゅう","zh":"這週"}],"examples":[{"jp":"今、日本語を勉強しています。","kana":"いま、にほんごをべんきょうしています。","zh":"現在正在學日文。"},{"jp":"台湾に住んでいます。","kana":"たいわんにすんでいます。","zh":"我住在台灣。"},{"jp":"切符を持っています。","kana":"きっぷをもっています。","zh":"我有車票。"}],"quiz":{"prompt":"「我不知道」通常說？","answer":"知りません","wrong":["知っていません","知りませんでした"],"why":"不知道一般用知りません；知っていません不是此處最自然表達。"}},{"id":30,"level":"N5","title":"把動作當一件事","pattern":"辞書形・こと・の","note":"一段動詞ます形去ます加る，如食べます→食べる；五段ます詞幹改回う段，如飲みます→飲む。動詞辭書形加こと或の可名詞化。","words":[{"jp":"趣味","kana":"しゅみ","zh":"興趣"},{"jp":"旅行する","kana":"りょこうする","zh":"旅行"},{"jp":"泳ぐ","kana":"およぐ","zh":"游泳"},{"jp":"歌う","kana":"うたう","zh":"唱歌"},{"jp":"走る","kana":"はしる","zh":"跑"},{"jp":"寝る","kana":"ねる","zh":"睡覺"},{"jp":"起きる","kana":"おきる","zh":"起床"},{"jp":"作る","kana":"つくる","zh":"製作"}],"examples":[{"jp":"趣味は写真を撮ることです。","kana":"しゅみはしゃしんをとることです。","zh":"興趣是拍照。"},{"jp":"歩くのが好きです。","kana":"あるくのがすきです。","zh":"我喜歡走路。"},{"jp":"毎日、早く寝ます。","kana":"まいにち、はやくねます。","zh":"每天早睡。"}],"quiz":{"prompt":"「喜歡走路」：歩く＿＿が好きです。","answer":"の","wrong":["に","を"],"why":"動詞加の可名詞化，作為好き的對象。"}},{"id":31,"level":"N5","title":"比較與選擇","pattern":"より・ほうが・いちばん","note":"AよりBのほうが表示B比A更…。二選一問どちら，多項選擇問どれ。いちばん表示最。","words":[{"jp":"早い","kana":"はやい","zh":"早"},{"jp":"速い","kana":"はやい","zh":"快"},{"jp":"遅い","kana":"おそい","zh":"晚／慢"},{"jp":"近い","kana":"ちかい","zh":"近"},{"jp":"遠い","kana":"とおい","zh":"遠"},{"jp":"暖かい","kana":"あたたかい","zh":"暖和"},{"jp":"涼しい","kana":"すずしい","zh":"涼爽"},{"jp":"一番","kana":"いちばん","zh":"最"}],"examples":[{"jp":"バスより電車のほうが速いです。","kana":"ばすよりでんしゃのほうがはやいです。","zh":"電車比公車快。"},{"jp":"どちらが安いですか。","kana":"どちらがやすいですか。","zh":"哪個比較便宜？"},{"jp":"春が一番好きです。","kana":"はるがいちばんすきです。","zh":"我最喜歡春天。"}],"quiz":{"prompt":"AよりBのほうが安いです，哪個便宜？","answer":"B","wrong":["A","兩者一樣"],"why":"より前面是比較基準，Bのほうが安い表示B較便宜。"}},{"id":32,"level":"N5","title":"說原因、接下一句","pattern":"から・そして・でも","note":"禮貌句或普通形後可接から表原因。名詞與な形容詞普通形後用だから。ので將在N4學習，語氣通常較柔和。","words":[{"jp":"雨","kana":"あめ","zh":"雨"},{"jp":"雪","kana":"ゆき","zh":"雪"},{"jp":"天気","kana":"てんき","zh":"天氣"},{"jp":"晴れ","kana":"はれ","zh":"晴天"},{"jp":"曇り","kana":"くもり","zh":"陰天"},{"jp":"傘","kana":"かさ","zh":"傘"},{"jp":"だから","kana":"だから","zh":"所以"},{"jp":"でも","kana":"でも","zh":"但是"}],"examples":[{"jp":"雨ですから、傘を持って行きます。","kana":"あめですから、かさをもっていきます。","zh":"因為下雨，所以帶傘去。"},{"jp":"安いです。でも、おいしいです。","kana":"やすいです。でも、おいしいです。","zh":"便宜，不過很好吃。"},{"jp":"静かです。そして、きれいです。","kana":"しずかです。そして、きれいです。","zh":"很安靜，而且很漂亮。"}],"quiz":{"prompt":"「因為下雨」的普通形接法？","answer":"雨だから","wrong":["雨から","雨いから"],"why":"名詞接原因から時，普通形用だから。"}},{"id":33,"level":"N4","title":"從禮貌形到普通形","pattern":"辞書形・ない形・た形","note":"普通形包含非過去、過去、肯定、否定。た形與て形規則相同，把て／で換成た／だ。名詞與な形容詞的普通形肯定常用だ。","words":[{"jp":"行った","kana":"いった","zh":"去了"},{"jp":"飲んだ","kana":"のんだ","zh":"喝了"},{"jp":"食べた","kana":"たべた","zh":"吃了"},{"jp":"買わない","kana":"かわない","zh":"不買"},{"jp":"来なかった","kana":"こなかった","zh":"沒有來"},{"jp":"だった","kana":"だった","zh":"曾經是"},{"jp":"週末","kana":"しゅうまつ","zh":"週末"},{"jp":"先週","kana":"せんしゅう","zh":"上週"}],"examples":[{"jp":"昨日、京都に行った。","kana":"きのう、きょうとにいった。","zh":"昨天去了京都（普通形）。"},{"jp":"朝ご飯は食べなかった。","kana":"あさごはんはたべなかった。","zh":"沒有吃早餐。"},{"jp":"昨日は雨だった。","kana":"きのうはあめだった。","zh":"昨天是雨天。"}],"quiz":{"prompt":"「行く」的た形是？","answer":"行った","wrong":["行いた","行きた"],"why":"行く的て／た形是例外：行って、行った。"}},{"id":34,"level":"N4","title":"說說你的經驗","pattern":"たことがある","note":"た形＋ことがある表示曾經有過經驗，不用來描述明確一次的昨日行程。沒有經驗是たことがありません。","words":[{"jp":"経験","kana":"けいけん","zh":"經驗"},{"jp":"初めて","kana":"はじめて","zh":"第一次"},{"jp":"一度","kana":"いちど","zh":"一次"},{"jp":"何度も","kana":"なんども","zh":"好幾次"},{"jp":"登る","kana":"のぼる","zh":"攀登"},{"jp":"泊まる","kana":"とまる","zh":"住宿"},{"jp":"乗る","kana":"のる","zh":"搭乘"},{"jp":"外国","kana":"がいこく","zh":"外國"}],"examples":[{"jp":"京都に行ったことがあります。","kana":"きょうとにいったことがあります。","zh":"我去過京都。"},{"jp":"旅館に泊まったことがありません。","kana":"りょかんにとまったことがありません。","zh":"我沒有住過日式旅館。"},{"jp":"抹茶を飲んだことがありますか。","kana":"まっちゃをのんだことがありますか。","zh":"你喝過抹茶嗎？"}],"quiz":{"prompt":"「曾經吃過」：食べ＿＿ことがあります。","answer":"た","wrong":["て","る"],"why":"描述經驗用た形＋ことがある。"}},{"id":35,"level":"N4","title":"列舉旅途的小事","pattern":"たり〜たりする・し〜し","note":"た形＋り列舉代表性活動，不表示只做這幾件。普通形＋し可列舉理由，名詞與な形容詞常用だし。","words":[{"jp":"美術館","kana":"びじゅつかん","zh":"美術館"},{"jp":"博物館","kana":"はくぶつかん","zh":"博物館"},{"jp":"市場","kana":"いちば","zh":"市場"},{"jp":"町","kana":"まち","zh":"城鎮"},{"jp":"探す","kana":"さがす","zh":"尋找"},{"jp":"選ぶ","kana":"えらぶ","zh":"挑選"},{"jp":"遊ぶ","kana":"あそぶ","zh":"玩"},{"jp":"楽しむ","kana":"たのしむ","zh":"享受"}],"examples":[{"jp":"お寺を見たり、写真を撮ったりします。","kana":"おてらをみたり、しゃしんをとったりします。","zh":"看看寺院、拍拍照。"},{"jp":"安いし、おいしいし、この店が好きです。","kana":"やすいし、おいしいし、このみせがすきです。","zh":"這間店又便宜又好吃，我喜歡。"},{"jp":"週末は歩いたり、休んだりしました。","kana":"しゅうまつはあるいたり、やすんだりしました。","zh":"週末走走路、休息休息。"}],"quiz":{"prompt":"列舉「吃吃、喝喝」：食べたり飲んだり＿＿。","answer":"します","wrong":["います","あります"],"why":"たり列舉最後通常以する結尾，依時態變成します或しました。"}},{"id":36,"level":"N4","title":"給一個溫柔建議","pattern":"たほうがいい・ないほうがいい","note":"肯定建議通常用た形＋ほうがいい；勸不要做則用ない形。語氣可能比中文「可以」更強，對陌生人使用時留意。","words":[{"jp":"疲れる","kana":"つかれる","zh":"疲累"},{"jp":"体","kana":"からだ","zh":"身體"},{"jp":"足","kana":"あし","zh":"腳"},{"jp":"痛い","kana":"いたい","zh":"痛"},{"jp":"無理","kana":"むり","zh":"勉強／不合理"},{"jp":"十分","kana":"じゅうぶん","zh":"充分"},{"jp":"早く","kana":"はやく","zh":"早點"},{"jp":"休み","kana":"やすみ","zh":"休息／假日"}],"examples":[{"jp":"少し休んだほうがいいです。","kana":"すこしやすんだほうがいいです。","zh":"最好休息一下。"},{"jp":"無理をしないほうがいいです。","kana":"むりをしないほうがいいです。","zh":"最好不要勉強。"},{"jp":"早く予約したほうがいいです。","kana":"はやくよやくしたほうがいいです。","zh":"最好早點預約。"}],"quiz":{"prompt":"勸對方不要勉強，接法是？","answer":"しないほうがいい","wrong":["したないほうがいい","してほうがいい"],"why":"否定建議用ない形＋ほうがいい。"}},{"id":37,"level":"N4","title":"必須與不必","pattern":"なければならない・なくてもいい","note":"ない形去い加ければならない表示必須；ない形去い加くてもいい表示不必。會話常聽到なきゃ或なくちゃ，先辨認即可。","words":[{"jp":"必要","kana":"ひつよう","zh":"必要"},{"jp":"約束","kana":"やくそく","zh":"約定"},{"jp":"時間","kana":"じかん","zh":"時間"},{"jp":"現金","kana":"げんきん","zh":"現金"},{"jp":"払う","kana":"はらう","zh":"支付"},{"jp":"急ぐ","kana":"いそぐ","zh":"趕快"},{"jp":"守る","kana":"まもる","zh":"遵守／守護"},{"jp":"準備","kana":"じゅんび","zh":"準備"}],"examples":[{"jp":"現金で払わなければなりません。","kana":"げんきんではらわなければなりません。","zh":"必須付現。"},{"jp":"急がなくてもいいです。","kana":"いそがなくてもいいです。","zh":"不用趕。"},{"jp":"予約しなければなりませんか。","kana":"よやくしなければなりませんか。","zh":"一定要預約嗎？"}],"quiz":{"prompt":"「不必去」是？","answer":"行かなくてもいい","wrong":["行かなければならない","行ってはいけない"],"why":"なくてもいい是不必；なければならない是必須；てはいけない是禁止。"}},{"id":38,"level":"N4","title":"我的旅行打算","pattern":"つもり・ことにする","note":"辭書形＋つもり表示打算，ない形＋つもり表示打算不做。ことにする表示自己決定，ことになる表示安排或外在決定。","words":[{"jp":"来年","kana":"らいねん","zh":"明年"},{"jp":"来月","kana":"らいげつ","zh":"下個月"},{"jp":"計画","kana":"けいかく","zh":"計畫"},{"jp":"予定","kana":"よてい","zh":"預定"},{"jp":"決める","kana":"きめる","zh":"決定"},{"jp":"長く","kana":"ながく","zh":"長時間地"},{"jp":"一人で","kana":"ひとりで","zh":"一個人"},{"jp":"今度","kana":"こんど","zh":"這次／下次"}],"examples":[{"jp":"来月、京都へ行くつもりです。","kana":"らいげつ、きょうとへいくつもりです。","zh":"打算下個月去京都。"},{"jp":"車は借りないつもりです。","kana":"くるまはかりないつもりです。","zh":"打算不租車。"},{"jp":"電車で行くことにしました。","kana":"でんしゃでいくことにしました。","zh":"我決定搭電車去。"}],"quiz":{"prompt":"「打算不買」是？","answer":"買わないつもりです","wrong":["買うつもりではありませんでした","買ってつもりです"],"why":"ない形＋つもり表示打算不做某事。"}},{"id":39,"level":"N4","title":"安排好的行程","pattern":"予定・ことになる","note":"動詞辭書形／ない形＋予定，名詞＋の予定。ことになっている可表示既定安排或規定。","words":[{"jp":"出発","kana":"しゅっぱつ","zh":"出發"},{"jp":"到着","kana":"とうちゃく","zh":"抵達"},{"jp":"集合","kana":"しゅうごう","zh":"集合"},{"jp":"変更","kana":"へんこう","zh":"變更"},{"jp":"中止","kana":"ちゅうし","zh":"取消／停止"},{"jp":"連絡","kana":"れんらく","zh":"聯絡"},{"jp":"日程","kana":"にってい","zh":"行程"},{"jp":"都合","kana":"つごう","zh":"方便與否／情況"}],"examples":[{"jp":"九時に出発する予定です。","kana":"くじにしゅっぱつするよていです。","zh":"預計九點出發。"},{"jp":"明日は休みの予定です。","kana":"あしたはやすみのよていです。","zh":"明天預計休息。"},{"jp":"入口で会うことになっています。","kana":"いりぐちであうことになっています。","zh":"已經約好在入口見面。"}],"quiz":{"prompt":"名詞「休み」接予定應該是？","answer":"休みの予定","wrong":["休みる予定","休みな予定"],"why":"名詞＋の予定；動詞用普通形接予定。"}},{"id":40,"level":"N4","title":"先做這個，再做那個","pattern":"てから・前に・後で","note":"てから表示先後順序；動詞辭書形＋前に；た形＋後で。名詞前用の前に／の後で。","words":[{"jp":"着く","kana":"つく","zh":"抵達"},{"jp":"出る","kana":"でる","zh":"離開"},{"jp":"戻る","kana":"もどる","zh":"返回"},{"jp":"預ける","kana":"あずける","zh":"寄放"},{"jp":"荷物","kana":"にもつ","zh":"行李"},{"jp":"食事","kana":"しょくじ","zh":"用餐"},{"jp":"受付","kana":"うけつけ","zh":"櫃檯"},{"jp":"終わる","kana":"おわる","zh":"結束"}],"examples":[{"jp":"荷物を預けてから、観光します。","kana":"にもつをあずけてから、かんこうします。","zh":"先寄放行李再觀光。"},{"jp":"出る前に、地図を見ます。","kana":"でるまえに、ちずをみます。","zh":"出門前看地圖。"},{"jp":"食べた後で、散歩します。","kana":"たべたあとで、さんぽします。","zh":"吃完後散步。"}],"quiz":{"prompt":"「吃完之後」：食べ＿＿後で。","answer":"た","wrong":["る","て"],"why":"後で前的動詞用た形。前に前則用辭書形。"}},{"id":41,"level":"N4","title":"當時、同時、之間","pattern":"とき・ながら・間に","note":"動詞普通形＋とき；名詞＋のとき，な形容詞＋なとき。ます詞幹＋ながら是同一人同時做兩件事。間に強調期間內發生一次的事。","words":[{"jp":"道","kana":"みち","zh":"道路"},{"jp":"迷う","kana":"まよう","zh":"迷路／猶豫"},{"jp":"音","kana":"おと","zh":"聲音"},{"jp":"聞こえる","kana":"きこえる","zh":"聽得見"},{"jp":"待ち時間","kana":"まちじかん","zh":"等候時間"},{"jp":"間","kana":"あいだ","zh":"期間／之間"},{"jp":"運転","kana":"うんてん","zh":"駕駛"},{"jp":"歩き方","kana":"あるきかた","zh":"走路方式"}],"examples":[{"jp":"道に迷ったとき、駅で聞きます。","kana":"みちにまよったとき、えきでききます。","zh":"迷路時在車站詢問。"},{"jp":"お茶を飲みながら、話します。","kana":"おちゃをのみながら、はなします。","zh":"邊喝茶邊聊天。"},{"jp":"友達を待っている間に、切符を買いました。","kana":"ともだちをまっているあいだに、きっぷをかいました。","zh":"等朋友時買了車票。"}],"quiz":{"prompt":"ながら前面的形式？","answer":"ます詞幹","wrong":["た形","ない形"],"why":"去掉ます接ながら，例如飲みます→飲みながら。"}},{"id":42,"level":"N4","title":"我能做到、可以使用","pattern":"可能形・ことができる","note":"五段う段改え段加る；一段去る加られる；する→できる、来る→こられる。可能的對象常用が；正式場合避免省略ら的說法。","words":[{"jp":"読める","kana":"よめる","zh":"能讀"},{"jp":"話せる","kana":"はなせる","zh":"能說"},{"jp":"食べられる","kana":"たべられる","zh":"能吃"},{"jp":"できる","kana":"できる","zh":"能做到"},{"jp":"使える","kana":"つかえる","zh":"能用"},{"jp":"見える","kana":"みえる","zh":"看得見"},{"jp":"予約","kana":"よやく","zh":"預約"},{"jp":"利用","kana":"りよう","zh":"使用"}],"examples":[{"jp":"少し日本語が話せます。","kana":"すこしにほんごがはなせます。","zh":"我會說一點日文。"},{"jp":"ここでカードが使えますか。","kana":"ここでかーどがつかえますか。","zh":"這裡可以用卡嗎？"},{"jp":"予約することができます。","kana":"よやくすることができます。","zh":"可以預約。"}],"quiz":{"prompt":"「食べる」的標準可能形？","answer":"食べられる","wrong":["食べれる","食べえる"],"why":"一段動詞去る加られる；口語有省略ら，但本課練標準形式。"}},{"id":43,"level":"N4","title":"說想法、轉述話語","pattern":"普通形＋と思う／と言う","note":"と前用普通形。名詞與な形容詞非過去肯定需だ：便利だと思います。引用實際話語也可使用引號。","words":[{"jp":"思う","kana":"おもう","zh":"想／認為"},{"jp":"言う","kana":"いう","zh":"說"},{"jp":"多分","kana":"たぶん","zh":"大概"},{"jp":"きっと","kana":"きっと","zh":"一定／想必"},{"jp":"本当","kana":"ほんとう","zh":"真的"},{"jp":"意味","kana":"いみ","zh":"意思"},{"jp":"説明","kana":"せつめい","zh":"說明"},{"jp":"質問","kana":"しつもん","zh":"問題／提問"}],"examples":[{"jp":"明日は晴れると思います。","kana":"あしたははれるとおもいます。","zh":"我想明天會放晴。"},{"jp":"この店は便利だと思います。","kana":"このみせはべんりだとおもいます。","zh":"我覺得這間店很方便。"},{"jp":"友達は九時に来ると言いました。","kana":"ともだちはくじにくるといいました。","zh":"朋友說九點會來。"}],"quiz":{"prompt":"「我覺得很安靜」是？","answer":"静かだと思います","wrong":["静かと思います","静かなと思います"],"why":"な形容詞普通形肯定用だ，再接と思います。"}},{"id":44,"level":"N4","title":"把句子放在名詞前","pattern":"普通形＋名詞","note":"日文修飾語放名詞前，不需要中文的「的」。動詞用普通形，例如昨日買った本。修飾子句的主語通常用が。","words":[{"jp":"人","kana":"ひと","zh":"人"},{"jp":"物","kana":"もの","zh":"東西"},{"jp":"場所","kana":"ばしょ","zh":"地方"},{"jp":"店員","kana":"てんいん","zh":"店員"},{"jp":"人気","kana":"にんき","zh":"人氣"},{"jp":"おすすめ","kana":"おすすめ","zh":"推薦"},{"jp":"昨日の","kana":"きのうの","zh":"昨天的"},{"jp":"次","kana":"つぎ","zh":"下一個"}],"examples":[{"jp":"昨日買ったお茶です。","kana":"きのうかったおちゃです。","zh":"是昨天買的茶。"},{"jp":"駅に行くバスはどれですか。","kana":"えきにいくばすはどれですか。","zh":"去車站的公車是哪一班？"},{"jp":"友達が教えてくれた店です。","kana":"ともだちがおしえてくれたみせです。","zh":"是朋友告訴我的店。"}],"quiz":{"prompt":"「昨天買的書」是？","answer":"昨日買った本","wrong":["昨日買いました本","昨日買ったの本"],"why":"動詞普通形直接修飾名詞，不加の。"}},{"id":45,"level":"N4","title":"補充背景，讓人理解","pattern":"んです・のです","note":"んです用來說明背景或請對方解釋。名詞和な形容詞後用なんです。陌生人問どうしたんですか有關心意味，語調要柔和。","words":[{"jp":"困る","kana":"こまる","zh":"困擾"},{"jp":"分かる","kana":"わかる","zh":"理解"},{"jp":"調子","kana":"ちょうし","zh":"狀況"},{"jp":"理由","kana":"りゆう","zh":"理由"},{"jp":"財布","kana":"さいふ","zh":"錢包"},{"jp":"なくす","kana":"なくす","zh":"遺失"},{"jp":"遅れる","kana":"おくれる","zh":"遲到／延誤"},{"jp":"どうして","kana":"どうして","zh":"為什麼"}],"examples":[{"jp":"道が分からないんです。","kana":"みちがわからないんです。","zh":"我不認得路（說明困境）。"},{"jp":"初めてなんです。","kana":"はじめてなんです。","zh":"因為我是第一次。"},{"jp":"どうしたんですか。","kana":"どうしたんですか。","zh":"怎麼了？"}],"quiz":{"prompt":"名詞「初めて」接んです時？","answer":"初めてなんです","wrong":["初めてんです","初めてだんです"],"why":"名詞和な形容詞接解釋語氣時用なんです。"}},{"id":46,"level":"N4","title":"柔和地說明原因","pattern":"ので・ために（目的）","note":"ので比から更常用於客觀說明；名詞與な形容詞接なので。目的用辭書形＋ために，名詞＋のために。","words":[{"jp":"混む","kana":"こむ","zh":"擁擠"},{"jp":"空く","kana":"すく","zh":"人少／空出"},{"jp":"用事","kana":"ようじ","zh":"事情"},{"jp":"予定表","kana":"よていひょう","zh":"行程表"},{"jp":"勉強する","kana":"べんきょうする","zh":"學習"},{"jp":"安全","kana":"あんぜん","zh":"安全"},{"jp":"気をつける","kana":"きをつける","zh":"小心"},{"jp":"ため","kana":"ため","zh":"目的／緣故"}],"examples":[{"jp":"道が混んでいるので、電車で行きます。","kana":"みちがこんでいるので、でんしゃでいきます。","zh":"因為塞車，搭電車去。"},{"jp":"静かなので、ここで休みます。","kana":"しずかなので、ここでやすみます。","zh":"因為安靜，在這裡休息。"},{"jp":"旅行のために、日本語を勉強しています。","kana":"りょこうのために、にほんごをべんきょうしています。","zh":"為了旅行學日文。"}],"quiz":{"prompt":"「因為安靜」用ので連接？","answer":"静かなので","wrong":["静かだので","静かいので"],"why":"な形容詞與名詞後用なので。"}},{"id":47,"level":"N4","title":"就算下雨也出發","pattern":"ても・のに","note":"ても表示即使；のに表示雖然卻，常含意外或不滿。い形容詞去い加くても；名詞與な形容詞用でも。のに前名詞用なのに。","words":[{"jp":"降る","kana":"ふる","zh":"下（雨雪）"},{"jp":"風","kana":"かぜ","zh":"風"},{"jp":"強い","kana":"つよい","zh":"強"},{"jp":"弱い","kana":"よわい","zh":"弱"},{"jp":"大丈夫","kana":"だいじょうぶ","zh":"沒關係"},{"jp":"残念","kana":"ざんねん","zh":"可惜"},{"jp":"まだ","kana":"まだ","zh":"仍然／還沒"},{"jp":"もう","kana":"もう","zh":"已經"}],"examples":[{"jp":"雨が降っても、行きます。","kana":"あめがふっても、いきます。","zh":"即使下雨也去。"},{"jp":"高くても、買いたいです。","kana":"たかくても、かいたいです。","zh":"即使貴也想買。"},{"jp":"予約したのに、席がありませんでした。","kana":"よやくしたのに、せきがありませんでした。","zh":"明明預約了，卻沒有座位。"}],"quiz":{"prompt":"「即使很貴」是？","answer":"高くても","wrong":["高いても","高いでも"],"why":"い形容詞去い加くても。"}},{"id":48,"level":"N4","title":"一做就會發生","pattern":"條件 と","note":"辭書形／ない形＋と常表自然結果、操作結果或固定習慣。後句通常不用命令、邀請或自己的意志。","words":[{"jp":"押す","kana":"おす","zh":"按／推"},{"jp":"引く","kana":"ひく","zh":"拉"},{"jp":"開く","kana":"あく","zh":"打開（自動）"},{"jp":"動く","kana":"うごく","zh":"移動／運作"},{"jp":"出る","kana":"でる","zh":"出現／出來"},{"jp":"曲がる","kana":"まがる","zh":"轉彎"},{"jp":"信号","kana":"しんごう","zh":"紅綠燈"},{"jp":"交差点","kana":"こうさてん","zh":"十字路口"}],"examples":[{"jp":"このボタンを押すと、切符が出ます。","kana":"このぼたんをおすと、きっぷがでます。","zh":"按這個按鈕就會出車票。"},{"jp":"右に曲がると、駅があります。","kana":"みぎにまがると、えきがあります。","zh":"右轉就有車站。"},{"jp":"春になると、暖かくなります。","kana":"はるになると、あたたかくなります。","zh":"到了春天就會變暖。"}],"quiz":{"prompt":"哪一句最適合用條件と？","answer":"按按鈕就會開門","wrong":["如果有空一起去吧","如果下雨請帶傘"],"why":"と常表自然或機械結果；邀請與請求通常改用たら等。"}},{"id":49,"level":"N4","title":"條件成立的話","pattern":"ば・ければ","note":"五段う段改え段加ば；一段去る加れば。い形容詞去い加ければ。名詞／な形容詞可用なら；條件的使用還要看後句語意。","words":[{"jp":"安ければ","kana":"やすければ","zh":"便宜的話"},{"jp":"よければ","kana":"よければ","zh":"可以／好的話"},{"jp":"行けば","kana":"いけば","zh":"去的話"},{"jp":"あれば","kana":"あれば","zh":"有的話"},{"jp":"なければ","kana":"なければ","zh":"沒有的話"},{"jp":"時間がある","kana":"じかんがある","zh":"有時間"},{"jp":"道順","kana":"みちじゅん","zh":"路線走法"},{"jp":"教科書","kana":"きょうかしょ","zh":"教科書"}],"examples":[{"jp":"安ければ、買います。","kana":"やすければ、かいます。","zh":"便宜的話就買。"},{"jp":"時間があれば、行きたいです。","kana":"じかんがあれば、いきたいです。","zh":"有時間的話想去。"},{"jp":"どう行けばいいですか。","kana":"どういけばいいですか。","zh":"該怎麼去？"}],"quiz":{"prompt":"「いい」的ば條件形？","answer":"よければ","wrong":["いければ","いいれば"],"why":"いい的變化以よい為基礎：よければ。"}},{"id":50,"level":"N4","title":"如果、等到之後","pattern":"たら・たらどうですか","note":"た形＋ら是用途廣的條件，也可表示完成前項後。後句可用請求、邀請、意志。たらどうですか可委婉建議。","words":[{"jp":"着いたら","kana":"ついたら","zh":"到了之後／如果抵達"},{"jp":"終わったら","kana":"おわったら","zh":"結束之後"},{"jp":"暇","kana":"ひま","zh":"有空"},{"jp":"雨だったら","kana":"あめだったら","zh":"如果下雨"},{"jp":"連休","kana":"れんきゅう","zh":"連假"},{"jp":"連れて行く","kana":"つれていく","zh":"帶某人去"},{"jp":"迎える","kana":"むかえる","zh":"迎接"},{"jp":"相談","kana":"そうだん","zh":"商量"}],"examples":[{"jp":"駅に着いたら、連絡してください。","kana":"えきについたら、れんらくしてください。","zh":"到車站後請聯絡我。"},{"jp":"雨だったら、博物館へ行きましょう。","kana":"あめだったら、はくぶつかんへいきましょう。","zh":"下雨的話去博物館吧。"},{"jp":"店員に聞いたらどうですか。","kana":"てんいんにきいたらどうですか。","zh":"問問店員如何？"}],"quiz":{"prompt":"「到達後請聯絡」最自然的連接？","answer":"着いたら","wrong":["着くと（請求）","着けばと"],"why":"たら後可接請求；と的自然結果用法通常不接請求。"}},{"id":51,"level":"N4","title":"說到這件事的話","pattern":"なら","note":"なら承接對方提到或假設的主題，提出資訊或建議。名詞可直接接なら；動詞普通形接なら。","words":[{"jp":"紅葉","kana":"こうよう","zh":"紅葉"},{"jp":"桜","kana":"さくら","zh":"櫻花"},{"jp":"季節","kana":"きせつ","zh":"季節"},{"jp":"春","kana":"はる","zh":"春天"},{"jp":"夏","kana":"なつ","zh":"夏天"},{"jp":"秋","kana":"あき","zh":"秋天"},{"jp":"冬","kana":"ふゆ","zh":"冬天"},{"jp":"朝早く","kana":"あさはやく","zh":"一大早"}],"examples":[{"jp":"京都へ行くなら、朝早く出るといいです。","kana":"きょうとへいくなら、あさはやくでるといいです。","zh":"如果要去京都，早點出門比較好。"},{"jp":"お茶なら、この店がおすすめです。","kana":"おちゃなら、このみせがおすすめです。","zh":"說到茶，推薦這間店。"},{"jp":"静かな場所なら、ここがいいです。","kana":"しずかなばしょなら、ここがいいです。","zh":"若要安靜的地方，這裡很好。"}],"quiz":{"prompt":"對方說想買茶，你承接話題用？","answer":"お茶なら","wrong":["お茶たら","お茶いと"],"why":"名詞可直接接なら，承接話題提供建議。"}},{"id":52,"level":"N4","title":"看起來好像","pattern":"樣態 そうです","note":"い形容詞去い、な形容詞直接接そう；いい→よさそう、ない→なさそう。動詞ます詞幹＋そう表示即將發生的樣子。","words":[{"jp":"おいしそう","kana":"おいしそう","zh":"看起來好吃"},{"jp":"よさそう","kana":"よさそう","zh":"看起來不錯"},{"jp":"降りそう","kana":"ふりそう","zh":"看起來快下雨"},{"jp":"眠い","kana":"ねむい","zh":"睏"},{"jp":"嬉しい","kana":"うれしい","zh":"高興"},{"jp":"重い","kana":"おもい","zh":"重"},{"jp":"軽い","kana":"かるい","zh":"輕"},{"jp":"難しい","kana":"むずかしい","zh":"難"}],"examples":[{"jp":"この料理はおいしそうです。","kana":"このりょうりはおいしそうです。","zh":"這道菜看起來好吃。"},{"jp":"雨が降りそうです。","kana":"あめがふりそうです。","zh":"看起來要下雨了。"},{"jp":"このホテルはよさそうです。","kana":"このほてるはよさそうです。","zh":"這飯店看起來不錯。"}],"quiz":{"prompt":"「看起來好吃」是？","answer":"おいしそうです","wrong":["おいしいそうです","おいしいだそうです"],"why":"樣態そう前，い形容詞去い。おいしいそう是聽說好吃。"}},{"id":53,"level":"N4","title":"聽說是這樣","pattern":"傳聞 そうです","note":"消息來源可用によると。普通形＋そうです表示聽說；名詞與な形容詞肯定用だそう。與樣態そう接法不同。","words":[{"jp":"天気予報","kana":"てんきよほう","zh":"天氣預報"},{"jp":"ニュース","kana":"にゅーす","zh":"新聞消息"},{"jp":"情報","kana":"じょうほう","zh":"資訊"},{"jp":"によると","kana":"によると","zh":"根據"},{"jp":"来週","kana":"らいしゅう","zh":"下週"},{"jp":"休館日","kana":"きゅうかんび","zh":"休館日"},{"jp":"台風","kana":"たいふう","zh":"颱風"},{"jp":"営業","kana":"えいぎょう","zh":"營業"}],"examples":[{"jp":"天気予報によると、明日は雨だそうです。","kana":"てんきよほうによると、あしたはあめだそうです。","zh":"根據預報，聽說明天下雨。"},{"jp":"この店はおいしいそうです。","kana":"このみせはおいしいそうです。","zh":"聽說這間店很好吃。"},{"jp":"来週は休みだそうです。","kana":"らいしゅうはやすみだそうです。","zh":"聽說下週休息。"}],"quiz":{"prompt":"「聽說很好吃」是？","answer":"おいしいそうです","wrong":["おいしそうです","おいしいなそうです"],"why":"傳聞前保留普通形おいしい；樣態才去い。"}},{"id":54,"level":"N4","title":"根據線索推測","pattern":"ようです・みたいです","note":"よう前接普通形，名詞用のよう、な形容詞用なよう。みたい較口語，名詞直接接みたい。用於根據線索的推測或比喻。","words":[{"jp":"よう","kana":"よう","zh":"好像／如同"},{"jp":"みたい","kana":"みたい","zh":"好像（口語）"},{"jp":"様子","kana":"ようす","zh":"樣子／情況"},{"jp":"留守","kana":"るす","zh":"不在家"},{"jp":"故障","kana":"こしょう","zh":"故障"},{"jp":"本物","kana":"ほんもの","zh":"真品"},{"jp":"静けさ","kana":"しずけさ","zh":"寂靜"},{"jp":"旅","kana":"たび","zh":"旅行"}],"examples":[{"jp":"店は休みのようです。","kana":"みせはやすみのようです。","zh":"店好像休息。"},{"jp":"電車が遅れているみたいです。","kana":"でんしゃがおくれているみたいです。","zh":"電車好像誤點了。"},{"jp":"雪のように白いです。","kana":"ゆきのようにしろいです。","zh":"像雪一樣白。"}],"quiz":{"prompt":"名詞「休み」接ようです？","answer":"休みのようです","wrong":["休みだようです","休みなようです"],"why":"名詞接よう時用の；な形容詞接な。"}},{"id":55,"level":"N4","title":"可能、大概、應該","pattern":"かもしれない・でしょう・はず","note":"普通形＋かもしれない表示可能，名詞與な形容詞去だ。でしょう表示推測；はず表示有根據的預期，名詞＋のはず。","words":[{"jp":"たぶん","kana":"たぶん","zh":"大概"},{"jp":"もしかしたら","kana":"もしかしたら","zh":"也許"},{"jp":"必ず","kana":"かならず","zh":"一定（確定／規律）"},{"jp":"きっと","kana":"きっと","zh":"想必"},{"jp":"間に合う","kana":"まにあう","zh":"趕得上"},{"jp":"遅刻","kana":"ちこく","zh":"遲到"},{"jp":"満員","kana":"まんいん","zh":"客滿"},{"jp":"空席","kana":"くうせき","zh":"空位"}],"examples":[{"jp":"電車に間に合わないかもしれません。","kana":"でんしゃにまにあわないかもしれません。","zh":"可能趕不上電車。"},{"jp":"明日は晴れるでしょう。","kana":"あしたははれるでしょう。","zh":"明天大概會放晴。"},{"jp":"予約したので、席があるはずです。","kana":"よやくしたので、せきがあるはずです。","zh":"因為預約了，應該有位子。"}],"quiz":{"prompt":"名詞「雨」接かもしれません是？","answer":"雨かもしれません","wrong":["雨だかもしれません","雨なかもしれません"],"why":"名詞與な形容詞接かもしれない時去掉だ。"}},{"id":56,"level":"N4","title":"試試看、先準備好","pattern":"てみる・ておく","note":"てみる表示嘗試做；ておく表示為後續先做。口語的とく來自ておく，例如買っとく。","words":[{"jp":"試す","kana":"ためす","zh":"嘗試"},{"jp":"調べる","kana":"しらべる","zh":"查詢"},{"jp":"確認","kana":"かくにん","zh":"確認"},{"jp":"用意","kana":"ようい","zh":"準備"},{"jp":"予約する","kana":"よやくする","zh":"預約"},{"jp":"充電","kana":"じゅうでん","zh":"充電"},{"jp":"電池","kana":"でんち","zh":"電池"},{"jp":"着替え","kana":"きがえ","zh":"換洗衣物"}],"examples":[{"jp":"このお茶を飲んでみます。","kana":"このおちゃをのんでみます。","zh":"試喝這個茶。"},{"jp":"先に切符を買っておきます。","kana":"さきにきっぷをかっておきます。","zh":"先買好車票。"},{"jp":"行き方を調べておいてください。","kana":"いきかたをしらべておいてください。","zh":"請先查好走法。"}],"quiz":{"prompt":"「先預約好」是？","answer":"予約しておきます","wrong":["予約してみました","予約していますだけ"],"why":"ておく表示為以後做準備。"}},{"id":57,"level":"N4","title":"不小心、全部做完","pattern":"てしまう・ちゃう／じゃう","note":"てしまう可表完成，也可表遺憾。てしまう口語縮為ちゃう；でしまう縮為じゃう。不要把所有しまう都理解成失誤。","words":[{"jp":"忘れ物","kana":"わすれもの","zh":"遺忘物"},{"jp":"落とす","kana":"おとす","zh":"掉落（他動）"},{"jp":"壊す","kana":"こわす","zh":"弄壞"},{"jp":"間違える","kana":"まちがえる","zh":"弄錯"},{"jp":"全部","kana":"ぜんぶ","zh":"全部"},{"jp":"売り切れる","kana":"うりきれる","zh":"售完"},{"jp":"残る","kana":"のこる","zh":"剩下"},{"jp":"残す","kana":"のこす","zh":"留下"}],"examples":[{"jp":"財布を忘れてしまいました。","kana":"さいふをわすれてしまいました。","zh":"不小心忘了帶錢包。"},{"jp":"全部食べてしまいました。","kana":"ぜんぶたべてしまいました。","zh":"全部吃完了。"},{"jp":"電車に乗り遅れちゃいました。","kana":"でんしゃにのりおくれちゃいました。","zh":"不小心沒趕上電車。"}],"quiz":{"prompt":"「飲んでしまった」的口語縮約？","answer":"飲んじゃった","wrong":["飲んちゃった","飲みちゃった"],"why":"でしまう縮約成じゃう，因此是飲んじゃった。"}},{"id":58,"level":"N4","title":"變得能、努力做到","pattern":"ようになる・ようにする・すぎる","note":"可能形＋ようになる表示變得能；辭書形／ない形＋ようにする表示刻意養成習慣。ます詞幹或形容詞詞幹＋すぎる表示過度。","words":[{"jp":"慣れる","kana":"なれる","zh":"習慣"},{"jp":"続ける","kana":"つづける","zh":"持續"},{"jp":"練習","kana":"れんしゅう","zh":"練習"},{"jp":"覚える","kana":"おぼえる","zh":"記住"},{"jp":"毎朝","kana":"まいあさ","zh":"每天早上"},{"jp":"毎晩","kana":"まいばん","zh":"每天晚上"},{"jp":"食べすぎる","kana":"たべすぎる","zh":"吃太多"},{"jp":"気分","kana":"きぶん","zh":"心情／身體感覺"}],"examples":[{"jp":"日本語が少し聞き取れるようになりました。","kana":"にほんごがすこしききとれるようになりました。","zh":"變得能聽懂一點日文了。"},{"jp":"毎日練習するようにしています。","kana":"まいにちれんしゅうするようにしています。","zh":"努力每天練習。"},{"jp":"食べすぎないようにします。","kana":"たべすぎないようにします。","zh":"我會注意不要吃太多。"}],"quiz":{"prompt":"「變得能讀」應該用？","answer":"読めるようになる","wrong":["読むようにするだけ","読みすぎる"],"why":"可能形＋ようになる表示能力的變化。"}},{"id":59,"level":"N4","title":"送出、收到與給我","pattern":"あげる・くれる・もらう","note":"我方給別人用あげる，別人給我方用くれる，我方從別人收到用もらう。給予者與接受者的視點很重要。","words":[{"jp":"あげる","kana":"あげる","zh":"給（我方給他方）"},{"jp":"くれる","kana":"くれる","zh":"給我方"},{"jp":"もらう","kana":"もらう","zh":"收到"},{"jp":"贈り物","kana":"おくりもの","zh":"禮物"},{"jp":"誕生日","kana":"たんじょうび","zh":"生日"},{"jp":"手紙","kana":"てがみ","zh":"信"},{"jp":"お菓子","kana":"おかし","zh":"點心"},{"jp":"祖母","kana":"そぼ","zh":"自己的祖母"}],"examples":[{"jp":"友達にお土産をあげました。","kana":"ともだちにおみやげをあげました。","zh":"我送朋友伴手禮。"},{"jp":"友達がお茶をくれました。","kana":"ともだちがおちゃをくれました。","zh":"朋友給我茶。"},{"jp":"母に手紙をもらいました。","kana":"ははにてがみをもらいました。","zh":"我收到了媽媽的信。"}],"quiz":{"prompt":"「朋友給我」應該用？","answer":"くれる","wrong":["あげる","もらわせる"],"why":"別人給我或我方成員，用くれる。"}},{"id":60,"level":"N4","title":"誰幫誰做一件事","pattern":"てあげる・てくれる・てもらう","note":"動詞て形接授受動詞，表示為某人做事。我請／得到對方幫忙用人に〜てもらう。直接對陌生人說てあげる可能顯得施恩。","words":[{"jp":"手伝う","kana":"てつだう","zh":"幫忙"},{"jp":"案内","kana":"あんない","zh":"帶路／介紹"},{"jp":"説明する","kana":"せつめいする","zh":"說明"},{"jp":"貸す","kana":"かす","zh":"借出"},{"jp":"借りる","kana":"かりる","zh":"借入"},{"jp":"送る","kana":"おくる","zh":"寄送／送行"},{"jp":"呼ぶ","kana":"よぶ","zh":"叫／呼叫"},{"jp":"親切","kana":"しんせつ","zh":"親切"}],"examples":[{"jp":"店員が道を教えてくれました。","kana":"てんいんがみちをおしえてくれました。","zh":"店員告訴了我路。"},{"jp":"友達に写真を撮ってもらいました。","kana":"ともだちにしゃしんをとってもらいました。","zh":"請朋友幫我拍了照。"},{"jp":"母の荷物を持ってあげました。","kana":"ははのにもつをもってあげました。","zh":"我幫媽媽拿了行李。"}],"quiz":{"prompt":"「請朋友幫我拍照」：友達に撮って＿＿。","answer":"もらいました","wrong":["あげました","ありました"],"why":"接受朋友幫忙，以我方為主語用てもらう。"}},{"id":61,"level":"N4","title":"發生在我身上的事","pattern":"受身形・自動詞／他動詞","note":"五段う段改あ段加れる，う→われる；一段去る加られる。する→される、来る→こられる。受身與自動詞不同：壊れた是自己壞了，壊された是被弄壞。","words":[{"jp":"言われる","kana":"いわれる","zh":"被說"},{"jp":"呼ばれる","kana":"よばれる","zh":"被叫"},{"jp":"盗まれる","kana":"ぬすまれる","zh":"被偷"},{"jp":"壊れる","kana":"こわれる","zh":"壞掉（自動）"},{"jp":"開ける","kana":"あける","zh":"打開（他動）"},{"jp":"開く","kana":"あく","zh":"開（自動）"},{"jp":"閉まる","kana":"しまる","zh":"關上（自動）"},{"jp":"閉める","kana":"しめる","zh":"關（他動）"}],"examples":[{"jp":"名前を呼ばれました。","kana":"なまえをよばれました。","zh":"名字被叫到了。"},{"jp":"財布を盗まれました。","kana":"さいふをぬすまれました。","zh":"錢包被偷了。"},{"jp":"窓が開いています。","kana":"まどがあいています。","zh":"窗戶開著。"}],"quiz":{"prompt":"「呼ぶ」的受身形？","answer":"呼ばれる","wrong":["呼べる","呼ばせる"],"why":"ぶ改ば加れる；呼べる是可能，呼ばせる是使役。"}},{"id":62,"level":"N4","title":"讓人做、容易做","pattern":"使役形・やすい／にくい","note":"五段う段改あ段加せる，う→わせる；一段去る加させる。する→させる、来る→こさせる。ます詞幹＋やすい／にくい表示容易／難以做。","words":[{"jp":"待たせる","kana":"またせる","zh":"讓人等"},{"jp":"知らせる","kana":"しらせる","zh":"通知"},{"jp":"参加","kana":"さんか","zh":"參加"},{"jp":"自由","kana":"じゆう","zh":"自由"},{"jp":"読みやすい","kana":"よみやすい","zh":"容易讀"},{"jp":"分かりにくい","kana":"わかりにくい","zh":"難懂"},{"jp":"運ぶ","kana":"はこぶ","zh":"搬運"},{"jp":"始める","kana":"はじめる","zh":"開始（他動）"}],"examples":[{"jp":"子供に好きな物を選ばせます。","kana":"こどもにすきなものをえらばせます。","zh":"讓小孩挑喜歡的東西。"},{"jp":"長く待たせて、すみません。","kana":"ながくまたせて、すみません。","zh":"抱歉讓您久等了。"},{"jp":"この地図は分かりやすいです。","kana":"このちずはわかりやすいです。","zh":"這張地圖很好懂。"}],"quiz":{"prompt":"「食べる」的使役形？","answer":"食べさせる","wrong":["食べられる","食べれる"],"why":"一段動詞去る加させる。"}},{"id":63,"level":"N4","title":"聽懂店員的敬語","pattern":"尊敬語・お〜になる・なさる","note":"尊敬語抬高對方的行為。いらっしゃる是行く／来る／いる，召し上がる是食べる／飲む，ご覧になる是見る。先練聽懂，不必逢人就用。","words":[{"jp":"いらっしゃる","kana":"いらっしゃる","zh":"去／來／在（尊敬）"},{"jp":"召し上がる","kana":"めしあがる","zh":"吃／喝（尊敬）"},{"jp":"ご覧になる","kana":"ごらんになる","zh":"看（尊敬）"},{"jp":"おっしゃる","kana":"おっしゃる","zh":"說（尊敬）"},{"jp":"なさる","kana":"なさる","zh":"做（尊敬）"},{"jp":"お客様","kana":"おきゃくさま","zh":"客人（敬稱）"},{"jp":"こちら","kana":"こちら","zh":"這邊（禮貌）"},{"jp":"お待ちください","kana":"おまちください","zh":"請稍候"}],"examples":[{"jp":"こちらで召し上がりますか。","kana":"こちらでめしあがりますか。","zh":"您要在這裡用餐嗎？"},{"jp":"少々お待ちください。","kana":"しょうしょうおまちください。","zh":"請稍等。"},{"jp":"何をご覧になりますか。","kana":"なにをごらんになりますか。","zh":"您想看什麼？"}],"quiz":{"prompt":"店員問「召し上がりますか」是在問？","answer":"要吃／喝嗎","wrong":["要看嗎","要離開嗎"],"why":"召し上がる是食べる與飲む的尊敬語。"}},{"id":64,"level":"N4","title":"把自己的話說得客氣","pattern":"謙讓語・いただく・伺う","note":"謙讓語降低自己的行為以尊重對方。いただく是もらう／食べる／飲む的謙讓語。ていただけますか是客氣請求；ございます是ある的鄭重語。","words":[{"jp":"いただく","kana":"いただく","zh":"領受／吃喝（謙讓）"},{"jp":"伺う","kana":"うかがう","zh":"拜訪／請教（謙讓）"},{"jp":"申す","kana":"もうす","zh":"說／名叫（謙讓）"},{"jp":"参る","kana":"まいる","zh":"去／來（謙讓）"},{"jp":"拝見する","kana":"はいけんする","zh":"看（謙讓）"},{"jp":"いたす","kana":"いたす","zh":"做（謙讓）"},{"jp":"ございます","kana":"ございます","zh":"有（鄭重）"},{"jp":"少々","kana":"しょうしょう","zh":"少許（禮貌）"}],"examples":[{"jp":"もう一度説明していただけますか。","kana":"もういちどせつめいしていただけますか。","zh":"可以請您再說明一次嗎？"},{"jp":"予約した陳と申します。","kana":"よやくしたちんともうします。","zh":"我是有預約的陳。"},{"jp":"明日、伺います。","kana":"あした、うかがいます。","zh":"明天前往拜訪。"}],"quiz":{"prompt":"請對方再說明一次，客氣的說法？","answer":"説明していただけますか","wrong":["説明してあげますか","説明いたしますか（請對方）"],"why":"ていただけますか是客氣請求對方為自己做事。"}},{"id":65,"level":"京都","title":"京都站，第一個問題","pattern":"すみません、〜はどこですか","note":"先叫住對方再問目的地。駅員是車站人員。八条口、中央口是練習用地名，實際出口和路線請看現場標示。","words":[{"jp":"駅員","kana":"えきいん","zh":"站務員"},{"jp":"改札","kana":"かいさつ","zh":"驗票口"},{"jp":"ホーム","kana":"ほーむ","zh":"月台"},{"jp":"中央口","kana":"ちゅうおうぐち","zh":"中央口"},{"jp":"八条口","kana":"はちじょうぐち","zh":"八條口"},{"jp":"案内所","kana":"あんないじょ","zh":"服務中心"},{"jp":"階段","kana":"かいだん","zh":"樓梯"},{"jp":"エレベーター","kana":"えれべーたー","zh":"電梯"}],"examples":[{"jp":"すみません、中央口はどこですか。","kana":"すみません、ちゅうおうぐちはどこですか。","zh":"不好意思，中央口在哪裡？"},{"jp":"この改札から出られますか。","kana":"このかいさつからでられますか。","zh":"可以從這個驗票口出去嗎？"},{"jp":"エレベーターはどちらですか。","kana":"えれべーたーはどちらですか。","zh":"電梯在哪邊？"}],"quiz":{"prompt":"要詢問月台，用哪個詞？","answer":"ホーム","wrong":["ホテル","ホール"],"why":"ホーム是月台，ホテル是飯店。"}},{"id":66,"level":"京都","title":"搭對車、問清楚轉乘","pattern":"〜に止まりますか・乗り換え","note":"班次、票價與轉乘會變，先學會核對目的地。普通列車也叫各駅停車。快速等列車可能略過某些站。","words":[{"jp":"普通","kana":"ふつう","zh":"普通列車"},{"jp":"快速","kana":"かいそく","zh":"快速列車"},{"jp":"特急","kana":"とっきゅう","zh":"特急"},{"jp":"乗り換え","kana":"のりかえ","zh":"轉乘"},{"jp":"片道","kana":"かたみち","zh":"單程"},{"jp":"往復","kana":"おうふく","zh":"來回"},{"jp":"終点","kana":"しゅうてん","zh":"終點站"},{"jp":"方面","kana":"ほうめん","zh":"方向"}],"examples":[{"jp":"この電車は京都駅に止まりますか。","kana":"このでんしゃはきょうとえきにとまりますか。","zh":"這班車停京都站嗎？"},{"jp":"どこで乗り換えればいいですか。","kana":"どこでのりかえればいいですか。","zh":"在哪裡轉車比較好？"},{"jp":"片道の切符を一枚ください。","kana":"かたみちのきっぷをいちまいください。","zh":"請給我一張單程票。"}],"quiz":{"prompt":"「轉乘」是哪個？","answer":"乗り換え","wrong":["往復","片道"],"why":"乗り換え指轉乘；往復是來回，片道是單程。"}},{"id":67,"level":"京都","title":"公車上聽懂下一站","pattern":"次は〜です・降ります","note":"不同車輛上下車與付費方式可能不同，以現場標示為準。這一課練習詢問與辨認，不寫死票價、路線或乘車規則。","words":[{"jp":"バス停","kana":"ばすてい","zh":"公車站"},{"jp":"次","kana":"つぎ","zh":"下一個"},{"jp":"降りる","kana":"おりる","zh":"下車"},{"jp":"運賃","kana":"うんちん","zh":"車資"},{"jp":"両替","kana":"りょうがえ","zh":"換零錢"},{"jp":"運転手","kana":"うんてんしゅ","zh":"司機"},{"jp":"整理券","kana":"せいりけん","zh":"整理券"},{"jp":"停留所","kana":"ていりゅうじょ","zh":"停靠站"}],"examples":[{"jp":"このバスは清水寺の近くに行きますか。","kana":"このばすはきよみずでらのちかくにいきますか。","zh":"這班車會到清水寺附近嗎？"},{"jp":"どこで降りればいいですか。","kana":"どこでおりればいいですか。","zh":"在哪裡下車？"},{"jp":"運賃はいつ払いますか。","kana":"うんちんはいつはらいますか。","zh":"什麼時候付車資？"}],"quiz":{"prompt":"聽到「次は」主要提示什麼？","answer":"下一個站／項目","wrong":["終點已到","禁止下車"],"why":"次は通常引出下一站或下一個項目，要再聽後面的站名。"}},{"id":68,"level":"京都","title":"進餐廳到點餐","pattern":"二人です・これをお願いします","note":"進門先說人數，有預約可先說予約しています。點餐用これをお願いします很實用。這裡的對話例句可當替換模板。","words":[{"jp":"席","kana":"せき","zh":"座位"},{"jp":"予約席","kana":"よやくせき","zh":"預約席"},{"jp":"注文","kana":"ちゅうもん","zh":"點餐"},{"jp":"定食","kana":"ていしょく","zh":"套餐"},{"jp":"うどん","kana":"うどん","zh":"烏龍麵"},{"jp":"そば","kana":"そば","zh":"蕎麥麵"},{"jp":"丼","kana":"どんぶり","zh":"丼飯"},{"jp":"おすすめ","kana":"おすすめ","zh":"推薦"}],"examples":[{"jp":"二人ですが、席はありますか。","kana":"ふたりですが、せきはありますか。","zh":"我們兩位，有座位嗎？"},{"jp":"おすすめは何ですか。","kana":"おすすめはなんですか。","zh":"推薦什麼？"},{"jp":"この定食を二つお願いします。","kana":"このていしょくをふたつおねがいします。","zh":"這套餐請給我們兩份。"}],"quiz":{"prompt":"點兩份套餐，數量用？","answer":"二つ","wrong":["二人","二枚"],"why":"套餐可用通用數量ふたつ；二人是人數。"}},{"id":69,"level":"京都","title":"飲食需求，確實問清楚","pattern":"〜が入っていますか・抜き","note":"アレルギー是過敏，不要只用苦手表達。對方說無法保證時，請依自己的需求決定，勿把「抜き」當作完全無交叉接觸的保證。","words":[{"jp":"アレルギー","kana":"あれるぎー","zh":"過敏"},{"jp":"卵","kana":"たまご","zh":"蛋"},{"jp":"乳製品","kana":"にゅうせいひん","zh":"乳製品"},{"jp":"小麦","kana":"こむぎ","zh":"小麥"},{"jp":"そば","kana":"そば","zh":"蕎麥"},{"jp":"肉","kana":"にく","zh":"肉"},{"jp":"魚","kana":"さかな","zh":"魚"},{"jp":"だし","kana":"だし","zh":"高湯"}],"examples":[{"jp":"卵のアレルギーがあります。","kana":"たまごのあれるぎーがあります。","zh":"我對蛋過敏。"},{"jp":"この料理に肉が入っていますか。","kana":"このりょうりににくがはいっていますか。","zh":"這道菜有放肉嗎？"},{"jp":"だしに魚を使っていますか。","kana":"だしにさかなをつかっていますか。","zh":"高湯有用魚嗎？"}],"quiz":{"prompt":"要明確表達食物過敏，用？","answer":"アレルギーがあります","wrong":["ちょっと苦手ですだけ","おいしそうです"],"why":"苦手只表示不喜歡或不擅長，不能清楚表達過敏。"}},{"id":70,"level":"京都","title":"一杯茶的從容","pattern":"店内・持ち帰り・温かい","note":"店內用餐常聽到店内で，外帶是持ち帰り。温かい形容飲料溫暖；暑い形容天氣，熱い則是燙。","words":[{"jp":"店内","kana":"てんない","zh":"店內"},{"jp":"持ち帰り","kana":"もちかえり","zh":"外帶"},{"jp":"温かい","kana":"あたたかい","zh":"溫暖的"},{"jp":"冷たい","kana":"つめたい","zh":"冰涼的"},{"jp":"砂糖","kana":"さとう","zh":"糖"},{"jp":"牛乳","kana":"ぎゅうにゅう","zh":"牛奶"},{"jp":"ほうじ茶","kana":"ほうじちゃ","zh":"焙茶"},{"jp":"和菓子","kana":"わがし","zh":"日式甜點"}],"examples":[{"jp":"温かいほうじ茶をお願いします。","kana":"あたたかいほうじちゃをおねがいします。","zh":"請給我溫熱的焙茶。"},{"jp":"持ち帰りでお願いします。","kana":"もちかえりでおねがいします。","zh":"我要外帶。"},{"jp":"砂糖なしでお願いします。","kana":"さとうなしでおねがいします。","zh":"請不要加糖。"}],"quiz":{"prompt":"店員問「店内で？」是在問？","answer":"在店裡用嗎","wrong":["要外帶嗎","要加糖嗎"],"why":"店内で表示在店裡用餐。"}},{"id":71,"level":"京都","title":"飯店入住與寄放行李","pattern":"予約した〜です・預かる","note":"自己把行李交給店家用預ける；店家替你保管用預かる。預かっていただけますか是請對方幫忙保管。","words":[{"jp":"チェックイン","kana":"ちぇっくいん","zh":"入住"},{"jp":"チェックアウト","kana":"ちぇっくあうと","zh":"退房"},{"jp":"予約番号","kana":"よやくばんごう","zh":"預約編號"},{"jp":"パスポート","kana":"ぱすぽーと","zh":"護照"},{"jp":"部屋","kana":"へや","zh":"房間"},{"jp":"鍵","kana":"かぎ","zh":"鑰匙"},{"jp":"預かる","kana":"あずかる","zh":"保管他人的物品"},{"jp":"荷物","kana":"にもつ","zh":"行李"}],"examples":[{"jp":"予約した陳です。","kana":"よやくしたちんです。","zh":"我是有預約的陳。"},{"jp":"荷物を預かっていただけますか。","kana":"にもつをあずかっていただけますか。","zh":"可以幫我保管行李嗎？"},{"jp":"チェックアウトは何時ですか。","kana":"ちぇっくあうとはなんじですか。","zh":"幾點退房？"}],"quiz":{"prompt":"請飯店保管行李時，對方的動作用？","answer":"預かる","wrong":["預ける","借りる"],"why":"店家保管用預かる；自己寄放用預ける。"}},{"id":72,"level":"京都","title":"住旅館、問使用方式","pattern":"〜方・〜てもいいですか","note":"ます詞幹＋方表示做法，如使い方。旅館與浴場規定各異，學會先問是否可以、何時可以使用。","words":[{"jp":"旅館","kana":"りょかん","zh":"日式旅館"},{"jp":"浴衣","kana":"ゆかた","zh":"浴衣"},{"jp":"お風呂","kana":"おふろ","zh":"浴池／洗澡"},{"jp":"温泉","kana":"おんせん","zh":"溫泉"},{"jp":"大浴場","kana":"だいよくじょう","zh":"公共大浴池"},{"jp":"貸切","kana":"かしきり","zh":"包場／獨享"},{"jp":"使い方","kana":"つかいかた","zh":"使用方法"},{"jp":"タオル","kana":"たおる","zh":"毛巾"}],"examples":[{"jp":"お風呂は何時まで使えますか。","kana":"おふろはなんじまでつかえますか。","zh":"浴池可以使用到幾點？"},{"jp":"使い方を教えてください。","kana":"つかいかたをおしえてください。","zh":"請告訴我使用方式。"},{"jp":"貸切のお風呂はありますか。","kana":"かしきりのおふろはありますか。","zh":"有獨立使用的浴池嗎？"}],"quiz":{"prompt":"「使用方法」是？","answer":"使い方","wrong":["使う方だけ","使って方"],"why":"ます詞幹使い加方，讀つかいかた。"}},{"id":73,"level":"京都","title":"買伴手禮，也聊兩句","pattern":"〜を探しています・試着","note":"正在找某物用探しています。試穿衣物是試着，試吃是試食。免稅與付款條件會變，直接詢問現場。","words":[{"jp":"お土産","kana":"おみやげ","zh":"伴手禮"},{"jp":"サイズ","kana":"さいず","zh":"尺寸"},{"jp":"色","kana":"いろ","zh":"顏色"},{"jp":"試着","kana":"しちゃく","zh":"試穿"},{"jp":"試食","kana":"ししょく","zh":"試吃"},{"jp":"免税","kana":"めんぜい","zh":"免稅"},{"jp":"袋","kana":"ふくろ","zh":"袋子"},{"jp":"包装","kana":"ほうそう","zh":"包裝"}],"examples":[{"jp":"お土産を探しています。","kana":"おみやげをさがしています。","zh":"我在找伴手禮。"},{"jp":"試着してもいいですか。","kana":"しちゃくしてもいいですか。","zh":"可以試穿嗎？"},{"jp":"別の色はありますか。","kana":"べつのいろはありますか。","zh":"有別的顏色嗎？"}],"quiz":{"prompt":"「可以試穿嗎？」用哪個詞？","answer":"試着","wrong":["試食","予約"],"why":"試着是試穿，試食是試吃。"}},{"id":74,"level":"京都","title":"結帳時不慌張","pattern":"お会計・別々・使えますか","note":"お会計お願いします可用在餐廳結帳；店員常說お支払いは。分開付款能否處理依店家而定。","words":[{"jp":"会計","kana":"かいけい","zh":"結帳"},{"jp":"支払い","kana":"しはらい","zh":"付款"},{"jp":"現金","kana":"げんきん","zh":"現金"},{"jp":"クレジットカード","kana":"くれじっとかーど","zh":"信用卡"},{"jp":"別々","kana":"べつべつ","zh":"分開"},{"jp":"一緒","kana":"いっしょ","zh":"一起"},{"jp":"レシート","kana":"れしーと","zh":"收據"},{"jp":"お釣り","kana":"おつり","zh":"找零"}],"examples":[{"jp":"お会計をお願いします。","kana":"おかいけいをおねがいします。","zh":"麻煩結帳。"},{"jp":"カードは使えますか。","kana":"かーどはつかえますか。","zh":"可以用卡嗎？"},{"jp":"別々に払えますか。","kana":"べつべつにはらえますか。","zh":"可以分開付嗎？"}],"quiz":{"prompt":"「お釣り」是？","answer":"找零","wrong":["訂金","車票"],"why":"お釣り指支付後找回的零錢。"}},{"id":75,"level":"京都","title":"寺院、神社與拍照","pattern":"撮影・拝観・〜てもいい","note":"這一課學習看懂標示與先問許可。每個寺社的開放區域和拍照規定都可能不同，依當日標示與人員說明。","words":[{"jp":"拝観","kana":"はいかん","zh":"參觀寺社"},{"jp":"拝観料","kana":"はいかんりょう","zh":"參觀費"},{"jp":"撮影","kana":"さつえい","zh":"拍攝"},{"jp":"撮影禁止","kana":"さつえいきんし","zh":"禁止拍攝"},{"jp":"参拝","kana":"さんぱい","zh":"參拜"},{"jp":"御朱印","kana":"ごしゅいん","zh":"御朱印"},{"jp":"境内","kana":"けいだい","zh":"寺社範圍"},{"jp":"本堂","kana":"ほんどう","zh":"正殿"}],"examples":[{"jp":"ここで写真を撮ってもいいですか。","kana":"ここでしゃしんをとってもいいですか。","zh":"這裡可以拍照嗎？"},{"jp":"拝観料はいくらですか。","kana":"はいかんりょうはいくらですか。","zh":"參觀費多少？"},{"jp":"御朱印はどこでいただけますか。","kana":"ごしゅいんはどこでいただけますか。","zh":"在哪裡可以領取御朱印？"}],"quiz":{"prompt":"看到「撮影禁止」應該理解為？","answer":"禁止拍攝","wrong":["只能拍照","可以錄影"],"why":"撮影包含拍照與錄影，禁止就不要拍攝。"}},{"id":76,"level":"京都","title":"預約體驗、確認時間","pattern":"予約できますか・何分ぐらい","note":"體驗前核對日期、人數、時間、費用與取消條件。日時是日期和時間，所要時間是需要的時間。","words":[{"jp":"体験","kana":"たいけん","zh":"體驗"},{"jp":"茶道","kana":"さどう","zh":"茶道"},{"jp":"着物","kana":"きもの","zh":"和服"},{"jp":"予約可能","kana":"よやくかのう","zh":"可預約"},{"jp":"日時","kana":"にちじ","zh":"日期時間"},{"jp":"所要時間","kana":"しょようじかん","zh":"所需時間"},{"jp":"料金","kana":"りょうきん","zh":"費用"},{"jp":"キャンセル","kana":"きゃんせる","zh":"取消"}],"examples":[{"jp":"明日の午後、二人で予約できますか。","kana":"あしたのごご、ふたりでよやくできますか。","zh":"可以預約明天下午兩位嗎？"},{"jp":"何分ぐらいかかりますか。","kana":"なんぷんぐらいかかりますか。","zh":"大約需要幾分鐘？"},{"jp":"料金に何が含まれていますか。","kana":"りょうきんになにがふくまれていますか。","zh":"費用包含什麼？"}],"quiz":{"prompt":"「所要時間」在問什麼？","answer":"需要多少時間","wrong":["集合地點","取消費用"],"why":"所要時間是完成活動需要的時間。"}},{"id":77,"level":"京都","title":"迷路、遺失與求助","pattern":"〜をなくしました・交番","note":"なくしました表示遺失，忘れました表示忘了或忘了帶。這是語言練習，緊急事件請直接尋求現場人員協助。","words":[{"jp":"交番","kana":"こうばん","zh":"派出所"},{"jp":"警察","kana":"けいさつ","zh":"警察"},{"jp":"忘れ物","kana":"わすれもの","zh":"遺忘物"},{"jp":"遺失物","kana":"いしつぶつ","zh":"遺失物"},{"jp":"携帯電話","kana":"けいたいでんわ","zh":"手機"},{"jp":"財布","kana":"さいふ","zh":"錢包"},{"jp":"助ける","kana":"たすける","zh":"幫助／救助"},{"jp":"見つかる","kana":"みつかる","zh":"被找到"}],"examples":[{"jp":"財布をなくしてしまいました。","kana":"さいふをなくしてしまいました。","zh":"我把錢包弄丟了。"},{"jp":"近くに交番はありますか。","kana":"ちかくにこうばんはありますか。","zh":"附近有派出所嗎？"},{"jp":"駅に忘れ物をしました。","kana":"えきにわすれものをしました。","zh":"我把東西忘在車站了。"}],"quiz":{"prompt":"遺失錢包最直接的說法？","answer":"財布をなくしました","wrong":["財布をもらいました","財布を借りました"],"why":"なくす是遺失，もらう是收到，借りる是借入。"}},{"id":78,"level":"京都","title":"藥局與身體不舒服","pattern":"〜が痛い・〜からです","note":"具體說明哪裡不舒服、何時開始。不要只說大丈夫來勉強自己。本課只教溝通句型，不提供診斷或用藥建議。","words":[{"jp":"薬局","kana":"やっきょく","zh":"藥局"},{"jp":"病院","kana":"びょういん","zh":"醫院"},{"jp":"頭","kana":"あたま","zh":"頭"},{"jp":"お腹","kana":"おなか","zh":"肚子"},{"jp":"喉","kana":"のど","zh":"喉嚨"},{"jp":"熱","kana":"ねつ","zh":"發燒／熱度"},{"jp":"気持ちが悪い","kana":"きもちがわるい","zh":"噁心／不舒服"},{"jp":"薬","kana":"くすり","zh":"藥"}],"examples":[{"jp":"頭が痛いです。","kana":"あたまがいたいです。","zh":"我頭痛。"},{"jp":"昨日からです。","kana":"きのうからです。","zh":"從昨天開始。"},{"jp":"近くの病院を教えていただけますか。","kana":"ちかくのびょういんをおしえていただけますか。","zh":"可以告訴我附近的醫院嗎？"}],"quiz":{"prompt":"「お腹が痛い」是？","answer":"肚子痛","wrong":["喉嚨痛","頭痛"],"why":"お腹讀おなか，指肚子。"}},{"id":79,"level":"京都","title":"和在地人聊一小段","pattern":"〜んです・〜たことがある","note":"先用天氣、食物、旅途等輕鬆話題。相槌そうなんですね表示有在聽；不要把京都旅途中聽見的方言誤認成標準教材。","words":[{"jp":"出身","kana":"しゅっしん","zh":"出身"},{"jp":"初めて","kana":"はじめて","zh":"第一次"},{"jp":"久しぶり","kana":"ひさしぶり","zh":"好久不見／久違"},{"jp":"素敵","kana":"すてき","zh":"很棒"},{"jp":"楽しかった","kana":"たのしかった","zh":"很開心（過去）"},{"jp":"また","kana":"また","zh":"再次"},{"jp":"ぜひ","kana":"ぜひ","zh":"務必／很希望"},{"jp":"そうなんですね","kana":"そうなんですね","zh":"原來如此"}],"examples":[{"jp":"京都は初めてなんです。","kana":"きょうとははじめてなんです。","zh":"我是第一次來京都。"},{"jp":"この辺でおすすめのお店はありますか。","kana":"このへんでおすすめのおみせはありますか。","zh":"這附近有推薦的店嗎？"},{"jp":"また来たいです。","kana":"またきたいです。","zh":"我還想再來。"}],"quiz":{"prompt":"自然表示「原來如此，我有在聽」？","answer":"そうなんですね","wrong":["知りませんでしたからです","お会計です"],"why":"そうなんですね是聽到新資訊時的自然回應。"}},{"id":80,"level":"京都","title":"一整天的京都，總複習","pattern":"提問 → 確認 → 感謝","note":"試著不看文字完成三件事：問路、點餐、請對方再說一次。能說出來是起點，接著練習聽懂對方的回答。複習過去與未來、請求與許可。","words":[{"jp":"午前","kana":"ごぜん","zh":"上午"},{"jp":"午後","kana":"ごご","zh":"下午"},{"jp":"午前中","kana":"ごぜんちゅう","zh":"上午期間"},{"jp":"夕方","kana":"ゆうがた","zh":"傍晚"},{"jp":"最後","kana":"さいご","zh":"最後"},{"jp":"最初","kana":"さいしょ","zh":"最初"},{"jp":"思い出","kana":"おもいで","zh":"回憶"},{"jp":"また今度","kana":"またこんど","zh":"下次再見／下次再說"}],"examples":[{"jp":"午前中はお寺を見て、午後はお茶を飲みました。","kana":"ごぜんちゅうはおてらをみて、ごごはおちゃをのみました。","zh":"上午看了寺院，下午喝了茶。"},{"jp":"明日はお土産を買うつもりです。","kana":"あしたはおみやげをかうつもりです。","zh":"明天打算買伴手禮。"},{"jp":"ゆっくり、もう一度言っていただけますか。","kana":"ゆっくり、もういちどいっていただけますか。","zh":"可以請您慢慢再說一次嗎？"}],"quiz":{"prompt":"想禮貌請對方慢慢再說一次，用？","answer":"ゆっくり、もう一度言っていただけますか","wrong":["早く言います","もう言わないでください"],"why":"ゆっくり是慢慢地，もう一度是再一次，ていただけますか是禮貌請求。"}}]};
